insert into public.art_movements (slug, name_ja, name_en, region, start_year, end_year, summary, body, source_url)
values ('renaissance', 'ルネサンス', 'Renaissance', 'west', 1400, 1600,
        '14〜16世紀のイタリアで始まり、古代ギリシャ・ローマの文化を手本に、人間と自然を目に見えるとおりに描こうとした美術の大きな転換期です。', 'ルネサンスは「再生」という意味の言葉です。14世紀ごろからイタリアのフィレンツェなどの都市で、商業で豊かになった市民や銀行家が芸術家を支えるようになりました。人々は古代ギリシャ・ローマの文学や彫刻を学び直し、神だけでなく人間そのものに関心を向けるようになります。この考え方が美術にも広がりました。

中世の絵では、人物は平たく、背景は金色で埋められることが多くありました。ルネサンスの画家たちは、遠くのものを小さく描く線遠近法や、明暗で立体感を出す方法を工夫し、画面の中に本物の空間があるように見せました。ブルネレスキやマサッチオが道を開き、15世紀末から16世紀初めにはレオナルド・ダ・ヴィンチ、ミケランジェロ、ラファエロが活躍して「盛期ルネサンス」と呼ばれる頂点を迎えます。アルプスの北でも、ヤン・ファン・エイクが油彩の技法をみがき、ドイツのデューラーはイタリアで学んだことを自国に持ち帰りました。ヴェネツィアではティツィアーノが色彩の豊かさで知られました。主題もキリスト教の物語に加えて、ギリシャ神話や実在の人物の肖像が増えていきます。

作品を見るときは、まず床や建物の線をたどって、消える一点（消失点）を探してみてください。画面がどれほど計算されて組み立てられているかがわかります。また、人物の顔や手の柔らかな陰影、輪郭をぼかした表現にも注目すると、描かれた人が生きているように感じられる理由が見えてきます。', 'https://ja.wikipedia.org/wiki/%E3%83%AB%E3%83%8D%E3%82%B5%E3%83%B3%E3%82%B9%E7%BE%8E%E8%A1%93')
