    name_ja = excluded.name_ja,
    name_en = excluded.name_en,
    region = excluded.region,
    start_year = excluded.start_year,
    end_year = excluded.end_year,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.art_movements (slug, name_ja, name_en, region, start_year, end_year, summary, body, source_url)
values ('baroque', 'バロック', 'Baroque', 'west', 1600, 1730,
        '17世紀を中心に広がった、強い明暗と動きのある構図で見る人の感情に直接うったえかける美術の様式です。', '16世紀に宗教改革が起こると、カトリック教会は信者の心をつなぎとめるために、わかりやすく感動的な宗教美術を求めました。同じころ、ヨーロッパ各地では国王が強い力を持つ絶対王政が広がり、権力を示す豪華な宮殿や肖像画も必要とされました。こうした背景のもとで、16世紀末から18世紀初めにかけてバロックと呼ばれる様式が生まれました。

ルネサンスの絵が安定した左右対称の構図を大切にしたのに対し、バロックの絵は斜めの線や大きな身ぶりを使い、一瞬の動きをとらえます。先がけとなったカラヴァッジョは、暗い背景に人物を強い光で浮かび上がらせる明暗法で、聖書の場面を目の前の出来事のように描きました。この表現はヨーロッパ中に広まり、イタリアのアルテミジア・ジェンティレスキ、フランドルのルーベンス、オランダのレンブラントやフェルメール、スペインのベラスケスなど、国ごとに個性ある画家が育ちます。カトリックの国では壮大な祭壇画が、商人が力を持ったオランダでは市民の集団肖像画や室内画が多く描かれたのも特徴です。

見どころは光の使い方です。光がどこから差し込み、画面のどこを照らしているかを追うと、画家が見る人の視線をどこへ導きたいのかがわかります。人物の手の動きや布の流れなど、止まった画面の中にある「動き」にも注目してみてください。', 'https://ja.wikipedia.org/wiki/%E3%83%90%E3%83%AD%E3%83%83%E3%82%AF%E7%BE%8E%E8%A1%93')
on conflict (slug) do update set
    name_ja = excluded.name_ja,
    name_en = excluded.name_en,
    region = excluded.region,
    start_year = excluded.start_year,
    end_year = excluded.end_year,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.art_movements (slug, name_ja, name_en, region, start_year, end_year, summary, body, source_url)
values ('rococo', 'ロココ', 'Rococo', 'west', 1720, 1789,
        '18世紀のフランス宮廷から広がった、淡い色と軽やかな曲線で貴族の優雅な暮らしや恋の楽しみを描いた様式です。', 'ルイ14世が亡くなった1715年以降、フランスの貴族たちは堅苦しいヴェルサイユの宮廷を離れ、パリの邸宅で親しい人々と集う「サロン」を楽しむようになりました。小さく居心地のよい室内には、貝殻や植物をかたどった曲線の装飾が好まれ、それを「ロカイユ」と呼んだことからロココという名前が生まれました。ポンパドゥール夫人のように芸術を支えた女性たちの存在も大きかったといわれます。

バロックが重々しく壮大だったのに対し、ロココの絵は明るいパステル調の色、軽い筆づかい、小ぶりな画面が特徴です。主題も、神々や英雄よりも、庭園で語らう恋人たちや、着飾った貴婦人の肖像が中心になりました。ヴァトーは野外で男女が集う「雅宴画（フェート・ギャラント）」という新しいジャンルを確立し、ブーシェは神話や肖像を華やかに描き、フラゴナールはいきいきとした筆で恋の場面を描きました。王妃マリー・アントワネットの肖像画家エリザベート・ヴィジェ＝ルブランは、フランス王立アカデミーに迎えられた数少ない女性画家の一人です。イギリスではゲインズバラが肖像画や風景画で活躍しました。

作品を見るときは、衣装のサテンやレースの光沢、肌の柔らかな色合いに目を近づけてみてください。また、物語の決定的な場面よりも、ささやかな仕草や視線のやりとりに意味が込められていることが多いので、人物どうしの目線を追うと楽しめます。', 'https://ja.wikipedia.org/wiki/%E3%83%AD%E3%82%B3%E3%82%B3')
on conflict (slug) do update set
    name_ja = excluded.name_ja,
    name_en = excluded.name_en,
    region = excluded.region,
    start_year = excluded.start_year,
    end_year = excluded.end_year,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.art_movements (slug, name_ja, name_en, region, start_year, end_year, summary, body, source_url)
values ('neoclassicism', '新古典主義', 'Neoclassicism', 'west', 1750, 1830,
        '18世紀後半、華やかなロココへの反発から、古代ギリシャ・ローマを手本に、はっきりした輪郭と理性的な構図を重んじた様式です。', '18世紀の前半、イタリアで古代都市ヘルクラネウムやポンペイの遺跡の発掘が進み、人々の古代への関心が高まりました。ドイツの研究者ヴィンケルマンは古代ギリシャの芸術をたたえる本を書き、各国に大きな影響を与えます。いっぽう、貴族の楽しみを描くロココは、甘く表面的だと批判されるようになっていました。そこで、古代の彫刻のように気高く、まじめな芸術が求められたのです。

新古典主義の絵画では、色よりも素描（デッサン）と形が重視されます。輪郭がくっきりしていて、筆の跡が目立たないなめらかな仕上げが特徴です。主題には、祖国のために命をかける英雄や、家族の美徳など、見る人に道徳を教える古代の物語がよく選ばれました。代表的な画家ダヴィッドは、フランス革命の時代に政治と深く関わり、のちにナポレオンの肖像も描いています。その弟子アングルは、なめらかな線で理想的な人体を追求しました。女性画家アンゲリカ・カウフマンは古代を題材にした歴史画で知られ、彫刻ではイタリアのカノーヴァが白い大理石で古代の理想美をよみがえらせました。

見どころは、画面の整った構成です。人物がまるで舞台の上に並ぶように配置され、柱や床の線が画面を区切っています。誰が何をしているのかが一目でわかるよう工夫されているので、身ぶりの意味を一つずつ読み取ってみてください。', 'https://ja.wikipedia.org/wiki/%E6%96%B0%E5%8F%A4%E5%85%B8%E4%B8%BB%E7%BE%A9')
on conflict (slug) do update set
    name_ja = excluded.name_ja,
    name_en = excluded.name_en,
    region = excluded.region,
    start_year = excluded.start_year,
    end_year = excluded.end_year,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.art_movements (slug, name_ja, name_en, region, start_year, end_year, summary, body, source_url)
values ('romanticism', 'ロマン主義', 'Romanticism', 'west', 1790, 1850,
        '18世紀末から19世紀前半、理性や規則よりも個人の感情、想像力、自然の大きさを大切にした芸術運動です。', '18世紀の終わりから19世紀の初め、ヨーロッパはフランス革命やナポレオン戦争、産業革命によって大きく揺れ動きました。古い秩序が崩れていく中で、決まった型に従う新古典主義に対して、一人ひとりの心の動きや、理屈では説明できない体験を表現しようとする考え方が強まります。これがロマン主義で、文学や音楽にも広がった運動でした。

絵画では、色彩と筆づかいの勢いが重んじられるようになりました。フランスのジェリコーやドラクロワは、難破や革命など同時代の劇的な出来事を、激しい動きと強い色で描きました。スペインのゴヤは戦争の残酷さを見つめ、ドイツのフリードリヒは霧や山、海を前にした小さな人間の姿を通して、自然への畏れや祈りの気持ちを表しました。イギリスではターナーが光と大気そのものを描こうとし、コンスタブルは身近な田園の風景を丹念に描きました。風景画が歴史画に負けない大切なジャンルになったのも、この時代の大きな変化です。新古典主義のアングルとロマン主義のドラクロワの対立は、「線か色か」という論争としてよく知られています。

作品の前では、まず全体から受ける感情を味わってみてください。そのうえで、空や海の描き方、筆の跡の荒々しさ、光と影の強い対比が、どのようにその感情を生み出しているのかを確かめると、ロマン主義の表現の工夫が見えてきます。', 'https://ja.wikipedia.org/wiki/%E3%83%AD%E3%83%9E%E3%83%B3%E4%B8%BB%E7%BE%A9')
on conflict (slug) do update set
    name_ja = excluded.name_ja,
    name_en = excluded.name_en,
    region = excluded.region,
    start_year = excluded.start_year,
    end_year = excluded.end_year,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.art_movements (slug, name_ja, name_en, region, start_year, end_year, summary, body, source_url)
values ('realism', '写実主義', 'Realism', 'west', 1840, 1880,
        '19世紀半ば、神話や英雄ではなく、同時代の農民や労働者など、目の前の現実をありのままに描こうとした運動です。', '19世紀のフランスでは、アカデミー（美術学校と公式展覧会サロンを動かす組織）が、神話や歴史を描いた絵を最も格が高いものとしていました。いっぽう、産業化が進んで都市には労働者があふれ、1848年には二月革命が起こるなど、社会は大きく変わっていました。ロマン主義の想像の世界にも、アカデミーの理想化された世界にも満足できない画家たちが、自分の目で見た現在を描こうとしたのが写実主義です。

中心人物のクールベは「天使は見たことがないから描かない」という趣旨の言葉で知られ、故郷の村の葬式や石を割る労働者を、歴史画のような大きな画面に描いて人々を驚かせました。ミレーはバルビゾン村に住み、畑で働く農民の姿を静かな尊厳をこめて描きました。ドーミエは都市の庶民や政治を風刺画と油彩で描き、動物画家ローザ・ボヌールは農村の牛や馬を正確な観察で描いて高い評価を得ました。この流れはロシアにも広がり、レーピンらが民衆の厳しい暮らしを描いています。

見どころは、描かれた人々の「普通さ」です。顔立ちを美しく整えず、汚れた服や疲れた姿勢がそのまま描かれていることに注目してください。そして、そうした人々がどれほど大きな画面に、どんな構図で描かれているかを見ると、画家が何を大切だと考えたのかが伝わってきます。', 'https://ja.wikipedia.org/wiki/%E5%86%99%E5%AE%9F%E4%B8%BB%E7%BE%A9')
on conflict (slug) do update set
    name_ja = excluded.name_ja,
    name_en = excluded.name_en,
    region = excluded.region,
    start_year = excluded.start_year,
    end_year = excluded.end_year,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.art_movements (slug, name_ja, name_en, region, start_year, end_year, summary, body, source_url)
values ('pre-raphaelite', 'ラファエル前派', 'Pre-Raphaelite Brotherhood', 'west', 1848, 1900,
        '1848年にイギリスの若い画家たちが結成したグループで、ラファエロ以前の美術を手本に、自然を細部まで正確に描こうとしました。', '19世紀半ばのイギリスでは、ロイヤル・アカデミーが教える、ラファエロを理想とする型どおりの描き方が主流でした。これに疑問を持ったロセッティ、ミレイ、ホルマン・ハントら若い学生たちが、1848年に「ラファエル前派兄弟団」を結成します。名前のとおり、ラファエロより前の初期ルネサンスや初期フランドルの絵画にあった、素直で誠実な表現に立ち返ろうとしたのです。批評家ジョン・ラスキンも彼らを支持しました。

彼らは自然をそのまま観察することを徹底し、草花の一本一本まで細かく描きました。白い下地の上に絵の具を重ねて、明るく澄んだ色を出す工夫もしています。主題には聖書、シェイクスピアやテニスンの文学、中世の伝説が多く選ばれました。グループとしての活動は数年で終わりましたが、ロセッティは後に夢のような女性像を描くようになり、その流れはバーン＝ジョーンズやウォーターハウスなどの世代に受け継がれました。会員ではなかったフォード・マドックス・ブラウンも、同じ考え方で現代の社会を描いています。

作品を見るときは、ぜひ画面の隅々まで近づいて見てください。背景の植物や布の模様まで同じ細かさで描かれていて、遠くのものがぼやけない独特の見え方をしています。また、花や小物には意味が込められていることが多いので、何が描かれているかを探すのも楽しみ方の一つです。', 'https://ja.wikipedia.org/wiki/%E3%83%A9%E3%83%95%E3%82%A1%E3%82%A8%E3%83%AB%E5%89%8D%E6%B4%BE')
