    updated_at = now();

insert into public.art_movements (slug, name_ja, name_en, region, start_year, end_year, summary, body, source_url)
values ('impressionism', '印象派', 'Impressionism', 'west', 1860, 1890,
        '19世紀後半のフランスで、移り変わる光や空気、都市の日常を、明るい色と素早い筆づかいでとらえようとした画家たちです。', '19世紀のパリでは、公式展覧会サロンに入選することが画家として認められる道でした。しかしサロンの審査は保守的で、モネやルノワールら若い画家の作品はたびたび落選しました。1863年、サロンに落ちたマネの「草上の昼食」は、落選展でスキャンダルとなり、新しい世代の注目を集めます。彼らは1874年、自分たちで独立した展覧会を開きました。モネの「印象・日の出」を見た批評家が皮肉をこめて「印象派」と呼んだことが、名前の由来です。

19世紀半ばにチューブ入りの絵の具が登場し、画家は屋外でも描きやすくなっていました。印象派の画家たちは、光の下で色が刻々と変わる様子をとらえるため、絵の具を混ぜずに小さな筆触を並べ、影にも色を使いました。主題は、カフェや踊り場、郊外の行楽、家庭の情景など、同時代の暮らしです。クールベら写実主義の「今を描く」姿勢を受け継ぎつつ、その描き方を大きく変えたといえます。ドガは踊り子や都会の人々を独特の構図で描き、ベルト・モリゾやアメリカ出身のメアリー・カサットは、女性や子どもの日常を親しみ深く描きました。日本の浮世絵の大胆な構図も、彼らに刺激を与えています。

見どころは、近くで見たときと離れて見たときの違いです。近くでは色の点や線にしか見えない部分が、数歩下がると水面のきらめきや木漏れ日に変わります。影が黒ではなく青や紫で描かれていることにも注目してみてください。', 'https://ja.wikipedia.org/wiki/%E5%8D%B0%E8%B1%A1%E6%B4%BE')
on conflict (slug) do update set
    name_ja = excluded.name_ja,
    name_en = excluded.name_en,
    region = excluded.region,
    start_year = excluded.start_year,
    end_year = excluded.end_year,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.art_movements (slug, name_ja, name_en, region, start_year, end_year, summary, body, source_url)
values ('post-impressionism', 'ポスト印象派', 'Post-Impressionism', 'west', 1880, 1905,
        '印象派の明るい色彩を出発点にしながら、形の確かさや画家の感情、象徴的な意味を求めて、それぞれ独自の道を進んだ画家たちです。', '1880年代になると、印象派の画家たちの中にも、光の一瞬をとらえるだけでは物足りないと感じる人が出てきました。印象派の絵は明るく生き生きとしていますが、形がぼやけ、画面の構成がゆるくなりがちだったからです。ポスト印象派（後期印象派とも訳されます）は、まとまった流派の名前ではなく、イギリスの批評家ロジャー・フライが1910年に開いた展覧会の名前に由来する呼び方で、印象派の後に現れた個性的な画家たちをまとめて指しています。

セザンヌは、自然を円筒や球のような基本の形でとらえ直し、いくつもの視点から見た形を一つの画面に組み立てました。スーラは色の点を科学的に並べる点描法を考え出しました。ゴッホは強い色と渦を巻くような筆づかいで自分の感情を表し、ゴーギャンはタヒチに渡って平らな色面と力強い輪郭で、文明や人生をめぐる問いを描きました。トゥールーズ＝ロートレックはパリの夜の娯楽の世界を鋭く描いています。ゴッホやロートレックは日本の浮世絵からも多くを学びました。彼らの試みは、20世紀のフォーヴィスムやキュビスム、表現主義へとつながっていきます。

作品を見るときは、同じ「印象派の後」でも画家ごとにまったく違う点を楽しんでください。セザンヌでは机や器の形のゆがみ、スーラでは点の並び方、ゴッホでは筆の向きと厚み、ゴーギャンでは輪郭線と色の組み合わせに注目すると、それぞれの狙いが見えてきます。', 'https://ja.wikipedia.org/wiki/%E3%83%9D%E3%82%B9%E3%83%88%E5%8D%B0%E8%B1%A1%E6%B4%BE')
on conflict (slug) do update set
