    updated_at = now();

insert into public.art_movements (slug, name_ja, name_en, region, start_year, end_year, summary, body, source_url)
values ('symbolism', '象徴主義', 'Symbolism', 'west', 1870, 1910,
        '19世紀後半、目に見える現実ではなく、夢や神話、死や魂といった目に見えないものを、象徴的なイメージで表そうとした運動です。', '19世紀後半のヨーロッパでは、科学や産業が急速に進み、美術でも現実をありのままに写す写実主義や自然主義、光をとらえる印象派が広がっていました。これに対して、人間の内面や神秘的な世界こそ表現すべきだと考えた詩人や画家たちがいました。1870年ごろからフランスやベルギーで広がったこの動きが象徴主義で、詩人ボードレールやマラルメの影響を強く受けています。ロマン主義の幻想的な側面を受け継ぎ、イギリスのラファエル前派が先に切り開いた夢のような女性像や中世への憧れとも響き合っています。

象徴主義の画家たちは、事物を正確に描くことよりも、神話や聖書、伝説の場面を借りて、愛や死、不安、理想といった観念を暗示しようとしました。フランスのギュスターヴ・モローは宝石のような細密な装飾で神話の世界を描き、ピュヴィス・ド・シャヴァンヌは淡い色の静かな画面をつくり、オディロン・ルドンは黒の版画や色鮮やかなパステルで不思議な生き物を描きました。スイスのベックリン、ベルギーのクノップフ、ウィーンのクリムトなど、各国に広がったことも特徴です。この運動はアール・ヌーヴォーなど世紀末の芸術にも大きな影響を与えました。

見どころは、画面に置かれたものが「何を意味しているか」を考えることです。花、目、水、閉ざされた扉など、くり返し現れるモチーフに注目してみてください。はっきりした答えはなくても、見る人それぞれが自由に想像をふくらませることが、象徴主義の楽しみ方です。', 'https://ja.wikipedia.org/wiki/%E8%B1%A1%E5%BE%B4%E4%B8%BB%E7%BE%A9')
on conflict (slug) do update set
    name_ja = excluded.name_ja,
    name_en = excluded.name_en,
    region = excluded.region,
    start_year = excluded.start_year,
    end_year = excluded.end_year,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.art_movements (slug, name_ja, name_en, region, start_year, end_year, summary, body, source_url)
values ('art-nouveau', 'アール・ヌーヴォー', 'Art Nouveau', 'west', 1890, 1914,
        '19世紀末から20世紀初めにヨーロッパで流行した、植物のような自由な曲線を特徴とする装飾の様式で、建築やポスターなど暮らしの中に広がりました。', '19世紀後半、工場で大量に作られる安価で質の低い製品が増えると、イギリスではウィリアム・モリスらが手仕事の美しさを取り戻そうとするアーツ・アンド・クラフツ運動を起こしました。こうした考えを受け継ぎ、過去の様式のまねではない「新しい芸術」をめざしたのがアール・ヌーヴォーです。名前は、パリの美術商サミュエル・ビングの店の名前から広まり、1900年のパリ万国博覧会で大きな注目を集めました。日本の浮世絵や工芸品が西洋で熱心に集められたジャポニスムも、平らな色面や自然のモチーフの取り入れ方に強い影響を与えています。

アール・ヌーヴォーの特徴は、花や茎、つる草、女性の長い髪などを思わせる流れるような曲線です。鉄やガラスといった新しい素材も積極的に使われました。絵画だけでなく、建築、家具、ガラス器、宝飾品、ポスターや本の挿絵まで、生活全体を美しくしようとしたことが大きな変化です。パリで活躍したチェコ出身のアルフォンス・ミュシャは、女優サラ・ベルナールの舞台ポスターで人気を集めました。イギリスのビアズリーは白と黒の挿絵で、フランスのエミール・ガレはガラス工芸で知られます。ウィーンではクリムトらがウィーン分離派を結成し、金を使った装飾的な絵画を生み出しました。

見どころは、文字や枠、背景の模様まで一つのデザインとしてまとめられている点です。ポスターでは、人物の髪や衣のひだが周りの装飾とつながっていく様子を追ってみてください。第一次世界大戦のころには、より直線的なアール・デコに移っていきます。', 'https://ja.wikipedia.org/wiki/%E3%82%A2%E3%83%BC%E3%83%AB%E3%83%BB%E3%83%8C%E3%83%BC%E3%83%B4%E3%82%A9%E3%83%BC')
