    name_ja = excluded.name_ja,
    name_en = excluded.name_en,
    region = excluded.region,
    start_year = excluded.start_year,
    end_year = excluded.end_year,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.art_movements (slug, name_ja, name_en, region, start_year, end_year, summary, body, source_url)
values ('fauvism', 'フォーヴィスム', 'Fauvism', 'west', 1905, 1908,
        '見たままの色ではなく、感じた色を画面いっぱいに使った20世紀初めのパリの絵画運動。「野獣派」とも呼ばれます。', '1905年、パリの展覧会サロン・ドートンヌに、原色をぶつけるように塗った絵が並びました。それを見た批評家ルイ・ヴォークセルが「野獣（フォーヴ）の檻のようだ」と書いたことから、この名前が生まれました。中心にいたのはアンリ・マティスとアンドレ・ドランで、モーリス・ド・ヴラマンク、ラウル・デュフィ、アルベール・マルケらも加わりました。背景には、ゴッホやゴーギャンが見せた強い色、スーラやシニャックの点描による色の研究など、後期印象派の試みがありました。

いちばん大きな変化は、色を「物の色を写す道具」から解き放ったことです。顔に緑の線を引き、木の幹を赤く、空をピンクに塗ってもかまわない。色は、画家が受けた感じや画面のリズムを伝えるためのものになりました。陰影で立体感を出すことも減り、平らな色の面と勢いのある筆の跡で画面が組み立てられます。

運動としてのまとまりは数年と短く、ドランやブラックはやがてキュビスムなど別の道へ進みました。それでも「色だけで絵が成り立つ」という考えは、ドイツの表現主義や、のちの抽象絵画へと受け継がれていきます。

見るときは、まず「現実ならこの色ではないはず」という所を探してみてください。そのうえで少し離れて、色どうしが響き合って画面全体が明るく見える感じを味わうと、画家が何をしたかったのかが伝わってきます。塗り残したキャンバスの白や、すばやい筆の動きにも注目です。', 'https://ja.wikipedia.org/wiki/%E3%83%95%E3%82%A9%E3%83%BC%E3%83%B4%E3%82%A3%E3%82%B9%E3%83%A0')
on conflict (slug) do update set
    name_ja = excluded.name_ja,
    name_en = excluded.name_en,
    region = excluded.region,
    start_year = excluded.start_year,
    end_year = excluded.end_year,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.art_movements (slug, name_ja, name_en, region, start_year, end_year, summary, body, source_url)
values ('expressionism', '表現主義', 'Expressionism', 'west', 1905, 1925,
        '外の世界の見た目より、不安や情熱など心の中を形と色でぶつけるように描いた、ドイツを中心とする芸術運動。', '20世紀の初め、都市が急に大きくなり、機械と人ごみの中で生きる不安を感じる人が増えていました。ノルウェーのエドヴァルド・ムンクや、ゴッホの激しい筆づかいは、そうした心の動きを絵にできることを示していました。これを受けて、1905年にドレスデンでエルンスト・ルートヴィヒ・キルヒナーらが「ブリュッケ（橋）」を結成し、1911年にはミュンヘンでワシリー・カンディンスキーとフランツ・マルクが「青騎士」を始めます。ウィーンのエゴン・シーレも、同じ時代に強い表現を追いました。

何が変わったかというと、絵の目的が「正しく写すこと」から「感じたことを伝えること」へはっきり移ったことです。形はゆがみ、輪郭はとがり、色は現実から離れて感情の色になります。木版画の荒い線もよく使われました。カンディンスキーはさらに進んで、音楽のように色と形だけで心を動かす抽象絵画にたどり着きました。

第一次世界大戦でマルクやアウグスト・マッケが戦死し、のちにナチスはこうした作品を「退廃芸術」として弾圧しました。それでも、内面を直接ぶつける表現は、戦後アメリカの抽象表現主義などにつながっていきます。

見るときは、人物の顔や体のゆがみ、不自然な色が、どんな気分を生んでいるかを感じてみてください。「きれいかどうか」より「どんな感情が伝わるか」を手がかりにすると、作品に入りやすくなります。', 'https://ja.wikipedia.org/wiki/%E8%A1%A8%E7%8F%BE%E4%B8%BB%E7%BE%A9')
on conflict (slug) do update set
    name_ja = excluded.name_ja,
    name_en = excluded.name_en,
    region = excluded.region,
    start_year = excluded.start_year,
    end_year = excluded.end_year,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.art_movements (slug, name_ja, name_en, region, start_year, end_year, summary, body, source_url)
values ('cubism', 'キュビスム', 'Cubism', 'west', 1907, 1920,
        'ものを一つの視点からではなく、いくつもの方向から見た形を一枚に組み合わせた、20世紀初めの絵画の大改革。', 'ルネサンス以来、西洋の絵は「一つの場所から見た風景」を遠近法で写すのが基本でした。ところがポール・セザンヌは、自然を円筒や球、円錐のような形でとらえ、少しずつ違う視点を一枚にまとめる絵を描きます。セザンヌが亡くなった翌年の1907年にはパリで回顧展が開かれます。こうしたセザンヌの試みに刺激を受けたパブロ・ピカソとジョルジュ・ブラックが、新しい絵画を一緒に探り始めました。批評家が「小さな立方体（キューブ）」と評したことが、名前の由来とされます。

変化は二つの段階で語られます。初めの「分析的キュビスム」では、ものを細かな面に分けて組み立て直し、色は茶色や灰色に抑えられました。1912年ごろからの「総合的キュビスム」では、新聞や壁紙を貼る「パピエ・コレ」やコラージュが登場し、絵の中に現実の素材が入り込みます。フアン・グリス、フェルナン・レジェ、ロベール・ドローネー、アルベール・グレーズらも、それぞれの方法で広げました。

この「見え方を分解して組み直す」考えは、イタリアの未来派、ロシアの前衛、ダダのコラージュ、そして抽象絵画へと広がり、20世紀美術の出発点の一つになりました。

見るときは、まず瓶やギター、顔の一部など、わかる形を探してみてください。正面と横からの形が同時に描かれている所が見つかると、画家が「見ること」そのものを問い直していたことが実感できます。', 'https://ja.wikipedia.org/wiki/%E3%82%AD%E3%83%A5%E3%83%93%E3%82%B9%E3%83%A0')
on conflict (slug) do update set
    name_ja = excluded.name_ja,
    name_en = excluded.name_en,
    region = excluded.region,
    start_year = excluded.start_year,
    end_year = excluded.end_year,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.art_movements (slug, name_ja, name_en, region, start_year, end_year, summary, body, source_url)
values ('futurism', '未来派', 'Futurism', 'west', 1909, 1944,
        '機械、スピード、都市の騒音を新しい時代の美として賛美した、イタリア発の芸術運動。動きそのものを描こうとしました。', '1909年、詩人フィリッポ・トンマーゾ・マリネッティがパリの新聞『フィガロ』に「未来派宣言」を発表しました。古い美術館や伝統を否定し、自動車の速さや工場の力強さこそ美しいと主張したのです。当時のイタリアは、栄光ある過去の美術で知られる一方、工業化が急速に進んでいました。翌1910年には、ウンベルト・ボッチョーニ、カルロ・カッラ、ルイジ・ルッソロ、ジャコモ・バッラ、ジーノ・セヴェリーニらが絵画の宣言を出しています。

未来派が新しく取り組んだのは「動き」と「時間」を一枚の絵に入れることです。走る馬や人を、連続写真のように何度も重ねて描き、力の向きを示す線で画面を満たしました。パリのキュビスムから、形を面に分ける方法も取り入れています。さらに、宣言文や朗読、騒音を使った音楽、建築の構想など、絵の外へも活動を広げました。

一方で、戦争を賛美する主張もあり、のちに運動の一部はファシズムと結びつきました。ボッチョーニは1916年に亡くなり、運動の勢いはそこで一つの区切りを迎えます。宣言やパフォーマンスで世の中に訴えるやり方は、ダダやロシアの前衛に受け継がれました。

見るときは、画面のどこからどこへ力が流れているかを目で追ってみてください。止まった絵なのに、音や速さ、ざわめきまで感じられるかどうかが、未来派を味わうポイントです。', 'https://ja.wikipedia.org/wiki/%E6%9C%AA%E6%9D%A5%E6%B4%BE')
on conflict (slug) do update set
    name_ja = excluded.name_ja,
    name_en = excluded.name_en,
    region = excluded.region,
    start_year = excluded.start_year,
    end_year = excluded.end_year,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.art_movements (slug, name_ja, name_en, region, start_year, end_year, summary, body, source_url)
values ('dada', 'ダダイスム', 'Dada', 'west', 1916, 1924,
        '第一次世界大戦のさなか、「芸術とは何か」という常識そのものを笑いと挑発でひっくり返した国際的な運動。', 'ダダは、第一次世界大戦の最中の1916年、中立国スイスのチューリヒで始まりました。戦争を逃れて集まった若い芸術家たちが、キャバレー・ヴォルテールという酒場で、意味のない音だけの詩を朗読したり、奇妙な衣装で舞台に立ったりしたのです。中心にはフーゴ・バル、トリスタン・ツァラ、ハンス・アルプ、ゾフィー・トイバー＝アルプらがいました。理性や進歩を信じた社会が大量の死を生んだことへの怒りと絶望が、その背景にあります。

ダダが変えたのは「芸術らしさ」の決まりです。新聞の切れ端や切符を貼るコラージュ、写真を切り貼りするフォトモンタージュ、偶然に任せた制作などが試されました。ニューヨークではマルセル・デュシャンが、既製品の男性用小便器にサインをして《泉》（1917年）と名づけ、「選ぶこと」も芸術になりうると問いかけました。ベルリン、ハノーファー、パリ、ケルンなどにも広がり、ハノーファーのクルト・シュヴィッタースは、拾ったゴミのような素材で「メルツ」と呼ぶ作品を作りました。

ダダは「何でもあり」のように見えますが、その問いはまじめです。のちのシュルレアリスム、ポップ・アート、コンセプチュアル・アートは、みなダダの問いを受け継いでいます。

見るときは「これが美術館にある理由」を考えてみてください。貼られた紙の文字を読んだり、素材の安っぽさにあえて目を向けたりすると、作者のユーモアと怒りの両方が見えてきます。', 'https://ja.wikipedia.org/wiki/%E3%83%80%E3%83%80%E3%82%A4%E3%82%B9%E3%83%A0')
on conflict (slug) do update set
    name_ja = excluded.name_ja,
    name_en = excluded.name_en,
    region = excluded.region,
    start_year = excluded.start_year,
    end_year = excluded.end_year,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.art_movements (slug, name_ja, name_en, region, start_year, end_year, summary, body, source_url)
values ('surrealism', 'シュルレアリスム', 'Surrealism', 'west', 1924, 1966,
        '夢や無意識の世界に、理性を超えたもう一つの現実を探した運動。ありえない組み合わせが不思議な詩を生みます。', '1924年、パリの詩人アンドレ・ブルトンが「シュルレアリスム宣言」を発表しました。ブルトンはダダの仲間でしたが、壊すだけでなく、新しいものを見つけたいと考えます。手がかりにしたのは、精神分析のフロイトが注目した夢と無意識でした。「シュルレアリスム」は「超現実主義」と訳され、現実を捨てるのではなく、現実の奥にあるもっと強い現実を探す、という意味がこめられています。

方法は大きく二つあります。一つは「オートマティスム（自動記述）」で、考えずに手を動かして、偶然に生まれる線や形を生かすやり方です。マックス・エルンストは板の木目を紙にこすり出す「フロッタージュ」を、ジョアン・ミロは記号のような自由な形を使いました。もう一つは、夢の場面のように、ありえない光景をきわめて写実的に描くやり方で、サルバドール・ダリやルネ・マグリット、イヴ・タンギーが知られます。運動は絵画だけでなく、詩、写真、映画、オブジェにも広がり、日本でも瀧口修造らが紹介しました。

第二次世界大戦のころ、多くのメンバーがアメリカへ逃れ、そのオートマティスムはニューヨークの若い画家たちに大きな影響を与えました。

見るときは、意味を一つに決めようとせず、「なぜここにこれが？」という違和感を楽しんでみてください。題名と画面のずれ、ふつうの物が置かれた場所の奇妙さに、作者が仕掛けた謎があります。夢を思い出すような気分で眺めるのが、いちばんの近道です。', 'https://ja.wikipedia.org/wiki/%E3%82%B7%E3%83%A5%E3%83%AB%E3%83%AC%E3%82%A2%E3%83%AA%E3%82%B9%E3%83%A0')
on conflict (slug) do update set
    name_ja = excluded.name_ja,
    name_en = excluded.name_en,
    region = excluded.region,
    start_year = excluded.start_year,
    end_year = excluded.end_year,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.art_movements (slug, name_ja, name_en, region, start_year, end_year, summary, body, source_url)
values ('abstract-expressionism', '抽象表現主義', 'Abstract Expressionism', 'west', 1943, 1960,
        '第二次世界大戦後のニューヨークで生まれた、巨大な画面に身ぶりや色の広がりで心の動きを示した抽象絵画。', '第二次世界大戦の前後、ヨーロッパから多くの芸術家がアメリカへ逃れ、美術の中心はパリからニューヨークへ移り始めます。シュルレアリスムのオートマティスムに触れた若い画家たちは、具体的な形を描かずに、描く行為そのものや色の広がりで人間の深い感情を表そうとしました。これが抽象表現主義で、アメリカ発の美術が初めて世界の注目を集めた運動とされます。

大きく分けて二つの流れがあります。一つは、体全体を使って描く「アクション・ペインティング」です。ジャクソン・ポロックは床に広げたキャンバスに絵具をたらしたり飛ばしたりし、ウィレム・デ・クーニングは激しい筆づかいで人物と抽象の間を行き来しました。もう一つは「カラーフィールド・ペインティング」で、マーク・ロスコやバーネット・ニューマンが、大きな色の面で見る人を包み込む画面を作りました。どちらも画面が非常に大きく、絵の前に立つ人の体験そのものが大切にされます。

1950年代末になると、この感情的で英雄的な絵画に対して、ポップ・アートやミニマル・アートが反発の形で生まれてきます。

見るときは、作品の前で少し時間をとってください。ポロックなら絵具の層の重なりや、線がどこへ向かうかを近くで追ってみる。ロスコなら近づいて色の境目のにじみを見たあと、離れて色に包まれる感じを味わう。「何が描いてあるか」ではなく「自分に何が起きるか」に気づくと楽しめます。', 'https://ja.wikipedia.org/wiki/%E6%8A%BD%E8%B1%A1%E8%A1%A8%E7%8F%BE%E4%B8%BB%E7%BE%A9')
on conflict (slug) do update set
    name_ja = excluded.name_ja,
    name_en = excluded.name_en,
    region = excluded.region,
    start_year = excluded.start_year,
    end_year = excluded.end_year,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.art_movements (slug, name_ja, name_en, region, start_year, end_year, summary, body, source_url)
values ('pop-art', 'ポップアート', 'Pop Art', 'west', 1956, 1970,
        '広告、漫画、スーパーの商品など、大量生産と大衆文化のイメージをそのまま美術に持ち込んだ運動です。', 'ポップ・アートは1950年代半ばのイギリスで芽生え、1960年代のアメリカで大きく花開きました。戦後の豊かな消費社会では、テレビ、雑誌広告、漫画、映画スターの写真があふれていました。ロンドンのリチャード・ハミルトンは、雑誌の切り抜きを集めたコラージュで、こうした身近なイメージを作品にしました。アメリカでは、抽象表現主義の重く個人的な絵画に対して、もっと軽やかで、誰もが知っているものを扱う作家たちが現れます。

何が変わったかというと、「高級な芸術」と「日常の安いイメージ」の境目が揺さぶられたことです。アンディ・ウォーホルは、キャンベル・スープの缶やマリリン・モンローの顔を、印刷の技法であるシルクスクリーンで繰り返し刷りました。ロイ・リキテンスタインは、漫画の一コマを印刷の網点まで大きく描き写し、クレス・オルデンバーグはハンバーガーなどを巨大な柔らかい彫刻にしました。手作業の跡や作者の個性を目立たせないことも、大きな特徴です。その前段には、日用品を作品にしたデュシャンや、ロバート・ラウシェンバーグ、ジャスパー・ジョーンズの試みがありました。

ポップ・アートは、イメージが大量に複製され消費される社会を映す鏡でもあり、その視点は今日の現代美術にもつながっています。

見るときは、「どこかで見たことがある」と感じるものを探してみてください。そして、同じ顔や商品が並ぶことで、かえって冷たく見えたり、さびしく見えたりしないか考えてみると、明るい画面の奥にある問いが見えてきます。', 'https://ja.wikipedia.org/wiki/%E3%83%9D%E3%83%83%E3%83%97%E3%82%A2%E3%83%BC%E3%83%88')
on conflict (slug) do update set
    name_ja = excluded.name_ja,
    name_en = excluded.name_en,
    region = excluded.region,
    start_year = excluded.start_year,
    end_year = excluded.end_year,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.art_movements (slug, name_ja, name_en, region, start_year, end_year, summary, body, source_url)
values ('minimal-conceptual', 'ミニマル・アートとコンセプチュアル・アート', 'Minimal Art and Conceptual Art', 'west', 1960, 1975,
        '形をぎりぎりまで削ったミニマル・アートと、物より「考え」そのものを作品とみなしたコンセプチュアル・アート。', '1960年代のアメリカでは、抽象表現主義の「画家の感情がこもった絵」への疑問が広がっていました。そこで現れたのがミニマル・アートです。ドナルド・ジャッドは金属や合板で作った同じ形の箱を並べ、ダン・フレイヴィンは市販の蛍光灯をそのまま作品にし、カール・アンドレは金属板やレンガを床に置きました。作者の手の跡や物語を取り去り、単純な形と工業製品の素材だけを示したのです。

そこから一歩進んで、「作品の本体は物ではなく考えだ」としたのがコンセプチュアル・アートです。ソル・ルウィットは、壁に描く線のルールを書いた指示書を作品の中心とし、ジョセフ・コスースは、実物の椅子、椅子の写真、辞書の「椅子」の説明を並べて、言葉とイメージと物の関係を問いました。日本出身の河原温は、1966年1月4日から、その日の日付だけを描く《Today》シリーズを続けました。ルーツには、既製品を作品にしたデュシャンがいます。

この二つは、見る人の体や空間、言葉、時間を作品に含める考え方を開き、のちのインスタレーションなど現代美術の土台になりました。

見るときは、「何もない」と感じたら、そこから始めてみてください。作品のまわりを歩くと、光や影、床との関係、自分の立つ位置で見え方が変わります。コンセプチュアルな作品では、解説や題名、指示の文章も作品の一部です。「なぜこの形・この言葉なのか」を考える時間そのものが鑑賞になります。', 'https://www.museum.or.jp/news/106565')
on conflict (slug) do update set
    name_ja = excluded.name_ja,
    name_en = excluded.name_en,
    region = excluded.region,
    start_year = excluded.start_year,
    end_year = excluded.end_year,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.art_movements (slug, name_ja, name_en, region, start_year, end_year, summary, body, source_url)
values ('contemporary', '現代美術', 'Contemporary Art', 'west', 1970, null,
        '1970年代から今日までの美術。空間全体を使うもの、映像、観客参加型など、形も素材も問いも多様に広がっています。', '1970年代以降の美術は、一つの「〇〇派」ではまとめられないほど多様になりました。ミニマル・アートやコンセプチュアル・アートが「作品は額縁の中の絵や台座の上の彫刻でなくてよい」ことを示し、ポップ・アートが社会にあふれるイメージを素材にしたことで、作家は何を使って何を問うてもよくなったのです。今日では世界各地の国際展や芸術祭が、新しい作品の発表の場になっています。

いくつかの方向を見てみましょう。一つは、部屋全体を作品にする「インスタレーション」です。塩田千春は、2015年のヴェネチア・ビエンナーレ日本館で、赤い糸と世界中から集めた鍵で空間を満たしました。草間彌生が1965年にニューヨークで発表した鏡の部屋の作品も、この流れの先駆けとされます。二つ目は映像やメディアを使う作品で、ナム・ジュン・パイクはテレビを素材にしたビデオ・アートの先駆者です。三つ目は観客が参加して初めて成り立つ作品、四つ目は環境、移民、歴史の記憶など社会の問題に向き合う作品です。日本出身では、アニメや漫画の感覚を取り込んだ「スーパーフラット」を2000年に打ち出した村上隆も国際的に活躍しています。

現代美術は過去と切れているわけではありません。デュシャンの問いや、ポップ・アートの大衆文化への目、ミニマル・アートの空間への意識が、形を変えて生きています。

見るときは、「わからない」と感じても大丈夫です。中を歩く、音を聞く、自分が映り込むなど、まず体で体験してみてください。そのあと解説を読み、「この作品は何を問いかけているか」を考えると、今の社会を映す鏡として楽しめます。', 'https://ja.wikipedia.org/wiki/%E7%8F%BE%E4%BB%A3%E7%BE%8E%E8%A1%93')
on conflict (slug) do update set
    name_ja = excluded.name_ja,
    name_en = excluded.name_en,
    region = excluded.region,
    start_year = excluded.start_year,
    end_year = excluded.end_year,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.movement_links (from_slug, to_slug, kind, note)
select a.slug, b.slug, 'led_to', 'ミケランジェロ晩年の力強い表現を先がけに、ルネサンスの均衡のとれた構図を崩して、動きと強い明暗を求めるバロックが生まれました。'
from public.art_movements a, public.art_movements b
where a.slug = 'renaissance' and b.slug = 'baroque'
