insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('アルノルフィーニ夫妻像', 'Arnolfini Portrait', 'ヤン・ファン・エイク', 'Jan van Eyck',
        1434,
        (select slug from public.art_movements where slug = 'renaissance'),
        'ロンドン・ナショナル・ギャラリー', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/33/Van_Eyck_-_Arnolfini_Portrait.jpg/960px-Van_Eyck_-_Arnolfini_Portrait.jpg', 'ブルッヘ（現在のベルギー）で活動したファン・エイクが、商人の夫婦を室内に描いた油彩画です。奥の壁の凸面鏡には二人の後ろ姿と入口に立つ人物まで映り込み、その上には「ヤン・ファン・エイクここにありき 1434」という意味のラテン語が書かれています。油絵の具を薄く何層も重ねる技法によって、毛皮や真鍮のシャンデリア、床に脱ぎ置かれた木靴まで驚くほど細かく描かれています。イタリアとは別に、アルプスの北で生まれた「北方ルネサンス」の写実の高さを示す一枚です。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('ヴィーナスの誕生', 'The Birth of Venus', 'サンドロ・ボッティチェッリ', 'Sandro Botticelli',
        1485,
        (select slug from public.art_movements where slug = 'renaissance'),
        'ウフィツィ美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0b/Sandro_Botticelli_-_La_nascita_di_Venere_-_Google_Art_Project_-_edited.jpg/960px-Sandro_Botticelli_-_La_nascita_di_Venere_-_Google_Art_Project_-_edited.jpg', 'フィレンツェで活躍したボッティチェッリが描いた、海から生まれた愛と美の女神ヴィーナスが貝殻に乗って岸にたどり着く場面です。中世にはあまり描かれなかったギリシャ神話の裸婦を大きな画面に描いたことは、古代への関心が高まったルネサンスならではの出来事でした。ただし体は彫刻のような立体感よりも、流れるような輪郭線の美しさで表されています。風に舞う髪や衣、散らばる花びらの動きを目で追うと、画面全体のリズムが感じられます。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('自画像', 'Self-Portrait with Fur-Trimmed Robe', 'アルブレヒト・デューラー', 'Albrecht Dürer',
        1500,
        (select slug from public.art_movements where slug = 'renaissance'),
        'アルテ・ピナコテーク（ミュンヘン）', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/40/D%C3%BCrer_Alte_Pinakothek.jpg/960px-D%C3%BCrer_Alte_Pinakothek.jpg', 'ドイツのニュルンベルクの画家デューラーが28歳ごろに描いた自画像です。真正面を向き、左右対称に整えられた姿は、それまでキリストの姿を描くときに使われた形式を思わせます。毛皮の襟の一本一本の毛や、胸元に添えられた手の描写は非常に細かく、画家としての自信がうかがえます。イタリアを旅してルネサンスの考え方を学んだデューラーは、画家を職人ではなく知性ある芸術家と考えていました。そうした意識が表れた作品として知られています。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('モナ・リザ', 'Mona Lisa', 'レオナルド・ダ・ヴィンチ', 'Leonardo da Vinci',
        1503,
        (select slug from public.art_movements where slug = 'renaissance'),
        'ルーヴル美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ec/Mona_Lisa%2C_by_Leonardo_da_Vinci%2C_from_C2RMF_retouched.jpg/960px-Mona_Lisa%2C_by_Leonardo_da_Vinci%2C_from_C2RMF_retouched.jpg', 'レオナルドが1503年ごろに描き始め、その後も長く手を加え続けた女性の肖像画です。輪郭線を使わず、色と影を煙のように少しずつぼかしていく「スフマート」という技法で、口元や目元の表情が見るたびに変わるような印象を生み出しています。背景には遠くほど青くかすむ山や川が描かれ、空気の厚みで奥行きを表す工夫も見られます。人物の上半身を斜めに向けて両手まで描く構図は、その後の肖像画の手本となり、多くの画家に学ばれました。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('アテナイの学堂', 'The School of Athens', 'ラファエロ・サンツィオ', 'Raphael',
        1509,
        (select slug from public.art_movements where slug = 'renaissance'),
        'ヴァチカン宮殿（ヴァチカン美術館）', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/49/%22The_School_of_Athens%22_by_Raffaello_Sanzio_da_Urbino.jpg/960px-%22The_School_of_Athens%22_by_Raffaello_Sanzio_da_Urbino.jpg', 'ローマ教皇の部屋「署名の間」の壁に描かれたフレスコ画です。古代ギリシャの哲学者や学者たちが、大きなアーチのある建物の中に集まっています。中央の二人はプラトンとアリストテレスで、プラトンの顔はレオナルド・ダ・ヴィンチがモデルだとも言われます。床や天井の線はすべて二人の頭のあたりに集まるように描かれ、線遠近法が見事に使われています。古代の知恵をたたえ、調和のとれた空間をつくる、盛期ルネサンスを代表する作品です。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('ウルビーノのヴィーナス', 'Venus of Urbino', 'ティツィアーノ・ヴェチェッリオ', 'Titian',
        1538,
        (select slug from public.art_movements where slug = 'renaissance'),
        'ウフィツィ美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/34/Tiziano%27s_Venere_di_Urbino_%28from_The_History_BLog%29.jpg/960px-Tiziano%27s_Venere_di_Urbino_%28from_The_History_BLog%29.jpg', 'ヴェネツィア派の巨匠ティツィアーノが、のちにウルビーノ公となるグイドバルド・デッラ・ローヴェレのために描いた横たわる裸婦です。神話の女神の名前がついていますが、場所は当時の豪華な寝室で、奥では侍女たちが衣装箱をのぞき込んでいます。輪郭線よりも色の重なりで肌の柔らかさや温かみを表しているのが、ヴェネツィア派らしい特徴です。この構図は後の画家たちにくり返し引用され、19世紀にはマネが「オランピア」でこの絵を下敷きにしています。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('聖マタイの召命', 'The Calling of Saint Matthew', 'カラヴァッジョ', 'Caravaggio',
        1599,
        (select slug from public.art_movements where slug = 'baroque'),
        'サン・ルイジ・デイ・フランチェージ聖堂（ローマ）', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/59/Caravaggio_%E2%80%94_The_Calling_of_Saint_Matthew.jpg/960px-Caravaggio_%E2%80%94_The_Calling_of_Saint_Matthew.jpg', 'ローマの教会の礼拝堂のために描かれた、キリストが徴税人マタイを弟子に呼ぶ場面です。舞台は当時の酒場のような薄暗い部屋で、登場人物も同時代の服を着ています。右上から差し込む一筋の光が、キリストの指さす手と同じ方向に進み、テーブルの人々を照らし出します。聖書の物語を、見る人のすぐそばで起きている出来事のように描いたこの劇的な明暗法は、多くの画家に衝撃を与え、バロック絵画の大きな出発点の一つとなりました。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('キリスト昇架', 'The Elevation of the Cross', 'ピーテル・パウル・ルーベンス', 'Peter Paul Rubens',
        1610,
        (select slug from public.art_movements where slug = 'baroque'),
        'アントワープ聖母大聖堂', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a4/Peter_Paul_Rubens_-_Raising_of_the_Cross_%28Cathedral_of_Antwerp%29.jpg/960px-Peter_Paul_Rubens_-_Raising_of_the_Cross_%28Cathedral_of_Antwerp%29.jpg', 'イタリアで学んで故郷アントワープに戻ったルーベンスが、大聖堂のために描いた三連の祭壇画です。中央では、筋肉を張りつめた男たちが十字架を力いっぱい引き起こそうとしており、画面を斜めに横切る十字架が強い動きを生んでいます。ミケランジェロの力強い人体表現やカラヴァッジョの明暗法を吸収し、北ヨーロッパに持ち帰った作品です。ルネサンスの静かな安定とは異なる、見る人を巻き込むようなバロックの迫力がよく表れています。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('ホロフェルネスの首を斬るユディト', 'Judith Slaying Holofernes', 'アルテミジア・ジェンティレスキ', 'Artemisia Gentileschi',
        1612,
        (select slug from public.art_movements where slug = 'baroque'),
        'カポディモンテ美術館（ナポリ）', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4e/Artemisia_Gentileschi_-_Judith_Beheading_Holofernes_-_WGA8563.jpg/960px-Artemisia_Gentileschi_-_Judith_Beheading_Holofernes_-_WGA8563.jpg', '旧約聖書の外典に登場する、町を救うために敵将ホロフェルネスを討つ未亡人ユディトの物語を描いた作品です。アルテミジアは画家オラツィオ・ジェンティレスキの娘で、当時はまだ珍しい女性のプロの画家として活躍しました。暗闇から浮かぶ人物、腕の力の入り方、生々しい表情には、カラヴァッジョの影響がはっきり見られます。侍女とともに力を合わせる女性たちの姿は、同じ主題を描いた男性画家の作品とは違う迫力があると評価されています。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('夜警', 'The Night Watch', 'レンブラント・ファン・レイン', 'Rembrandt',
        1642,
        (select slug from public.art_movements where slug = 'baroque'),
        'アムステルダム国立美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3a/La_ronda_de_noche%2C_por_Rembrandt_van_Rijn.jpg/960px-La_ronda_de_noche%2C_por_Rembrandt_van_Rijn.jpg', 'アムステルダムの市民による自警団（火縄銃手組合）の隊長バニング・コックと隊員たちを描いた、大きな集団肖像画です。それまでの集団肖像画は人物を行儀よく並べるのが普通でしたが、レンブラントは隊が出発しようとする一瞬の動きの中に人々を配置しました。強い光と深い影の対比で、隊長や光を浴びた少女が浮かび上がります。実際は昼の場面ですが、表面のニスが黒ずんだことから後に「夜警」と呼ばれるようになりました。市民が注文主となったオランダらしいバロック絵画です。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('ラス・メニーナス', 'Las Meninas', 'ディエゴ・ベラスケス', 'Diego Velázquez',
        1656,
        (select slug from public.art_movements where slug = 'baroque'),
        'プラド美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/31/Las_Meninas%2C_by_Diego_Vel%C3%A1zquez%2C_from_Prado_in_Google_Earth.jpg/960px-Las_Meninas%2C_by_Diego_Vel%C3%A1zquez%2C_from_Prado_in_Google_Earth.jpg', 'スペイン国王フェリペ4世の宮廷画家ベラスケスが、王女マルガリータとその侍女たち（メニーナス）を描いた作品です。左側には大きなキャンバスに向かう画家自身の姿があり、奥の鏡には国王夫妻がぼんやりと映っています。つまり見る私たちは国王夫妻の立ち位置にいるようにも感じられ、「誰が誰を見ているのか」という問いが画面に込められています。近づくと粗く見える筆づかいが、離れると衣装の光沢に見えるのも見どころで、後の多くの画家が研究しました。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('真珠の耳飾りの少女', 'Girl with a Pearl Earring', 'ヨハネス・フェルメール', 'Johannes Vermeer',
        1665,
        (select slug from public.art_movements where slug = 'baroque'),
        'マウリッツハイス美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0f/1665_Girl_with_a_Pearl_Earring.jpg/960px-1665_Girl_with_a_Pearl_Earring.jpg', 'オランダのデルフトで活動したフェルメールが描いた、振り向いた少女の絵です。特定の人物の肖像ではなく、当時オランダで好まれた「トローニー」と呼ばれる、表情や衣装を描く人物画と考えられています。暗い背景の中で、ターバンの青と黄色、唇のつや、真珠の光が際立っています。真珠はわずかな白と灰色の筆跡だけで表されています。カラヴァッジョのような劇的な明暗とは違い、静かな光で人物を包み込むところに、オランダ・バロックの落ち着いた魅力があります。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('シテール島の巡礼', 'The Embarkation for Cythera', 'アントワーヌ・ヴァトー', 'Jean-Antoine Watteau',
        1717,
        (select slug from public.art_movements where slug = 'rococo'),
        'ルーヴル美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/28/L%27Embarquement_pour_Cyth%C3%A8re%2C_by_Antoine_Watteau%2C_from_C2RMF_retouched.jpg/960px-L%27Embarquement_pour_Cyth%C3%A8re%2C_by_Antoine_Watteau%2C_from_C2RMF_retouched.jpg', 'ヴァトーが1717年にフランス王立アカデミーに提出した作品で、これにより「雅宴画（フェート・ギャラント）」という新しいジャンルの画家として認められました。愛の女神ヴィーナスの島シテールをめぐる、着飾った男女の一行が描かれています。右から左へ、恋人たちがゆっくり立ち上がり、船の方へ向かう流れになっており、恋の進み具合を表しているとも解釈されます。かすんだ空気や柔らかな色彩は、重厚なバロックからロココへの変化を告げるものでした。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('ポンパドゥール夫人', 'Portrait of Madame de Pompadour', 'フランソワ・ブーシェ', 'François Boucher',
        1756,
        (select slug from public.art_movements where slug = 'rococo'),
        'アルテ・ピナコテーク（ミュンヘン）', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/82/Madame_de_Pompadour.jpg/960px-Madame_de_Pompadour.jpg', 'ルイ15世の寵愛を受け、芸術や学問の保護者としても知られたポンパドゥール夫人を、ブーシェが描いた肖像画です。夫人は花飾りやリボンをたくさんつけた淡い青緑色のドレスを着て、手には本を持ち、足元にも書物などが置かれています。華やかな装いの中に教養の高さを示す品々を描き込んでいる点が特徴です。サテンの光沢やバラの飾りの細かな描写には、ロココ盛期を代表する画家ブーシェの技量と、宮廷の華やかな好みがよく表れています。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('ぶらんこ', 'The Swing', 'ジャン・オノレ・フラゴナール', 'Jean-Honoré Fragonard',
        1767,
        (select slug from public.art_movements where slug = 'rococo'),
        'ウォレス・コレクション（ロンドン）', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/eb/Fragonard%2C_The_Swing.jpg/960px-Fragonard%2C_The_Swing.jpg', '木々の茂る庭でぶらんこに乗る若い女性と、それを茂みの中から見上げる男性、後ろで綱を引く年配の男性を描いた作品です。女性の脚から飛んだピンクの靴が宙に舞い、その一瞬の軽やかさが画面の中心になっています。左手前の彫像は唇に指を当て、「内緒」の合図をしているように見えます。淡い緑とピンクの色調、くるくると渦を巻くような木々の形は、ロココ後期の楽しさをよく表しています。後に新古典主義の時代には、こうした絵は軽薄だと批判されました。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('青衣の少年', 'The Blue Boy', 'トマス・ゲインズバラ', 'Thomas Gainsborough',
        1770,
        (select slug from public.art_movements where slug = 'rococo'),
        'ハンティントン・ライブラリー（カリフォルニア）', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/46/Thomas_Gainsborough_-_The_Blue_Boy_%28c._1770%29.jpg/960px-Thomas_Gainsborough_-_The_Blue_Boy_%28c._1770%29.jpg', 'ロココの時代のイギリスで活躍した肖像画家ゲインズバラの代表作です。少年が着ている青いサテンの衣装は、当時の流行ではなく、17世紀にイギリスで活躍したヴァン・ダイクの肖像画に見られる服装を思わせるもので、先輩画家への敬意が込められていると考えられています。軽く素早い筆づかいで布の光沢が表され、背景の風景も柔らかく描かれています。イギリスを代表する名画として知られ、20世紀にアメリカのコレクターが購入したことでも話題になりました。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('バラを持つマリー・アントワネット', 'Marie Antoinette with a Rose', 'エリザベート・ヴィジェ＝ルブラン', 'Élisabeth Louise Vigée Le Brun',
        1783,
        (select slug from public.art_movements where slug = 'rococo'),
        'ヴェルサイユ宮殿', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5f/Louise_Elisabeth_Vig%C3%A9e-Lebrun_-_Marie-Antoinette_dit_%C2%AB_%C3%A0_la_Rose_%C2%BB_-_Google_Art_Project.jpg/960px-Louise_Elisabeth_Vig%C3%A9e-Lebrun_-_Marie-Antoinette_dit_%C2%AB_%C3%A0_la_Rose_%C2%BB_-_Google_Art_Project.jpg', '王妃マリー・アントワネットの肖像画家だったヴィジェ＝ルブランの作品です。同じ1783年、彼女は木綿のシンプルなドレスを着た王妃の肖像をサロンに出品しましたが、王妃にふさわしくないと批判され、ほぼ同じポーズで絹のドレスを着たこの肖像に描き直しました。淡い青灰色のドレスと手に持つバラが、柔らかな光の中で優雅にまとめられています。この年、彼女はフランス王立アカデミーの会員に迎えられました。フランス革命直前の宮廷文化を伝える一枚です。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('ホラティウス兄弟の誓い', 'The Oath of the Horatii', 'ジャック＝ルイ・ダヴィッド', 'Jacques-Louis David',
        1784,
        (select slug from public.art_movements where slug = 'neoclassicism'),
        'ルーヴル美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bd/Le_Serment_des_Horaces_-_Jacques-Louis_David_-_Mus%C3%A9e_du_Louvre_Peintures_INV_3692_%3B_MR_1432.jpg/960px-Le_Serment_des_Horaces_-_Jacques-Louis_David_-_Mus%C3%A9e_du_Louvre_Peintures_INV_3692_%3B_MR_1432.jpg', '古代ローマの伝説を題材に、祖国のために敵国の三兄弟と戦うことを誓うホラティウス家の三兄弟と、剣を掲げる父を描いた作品です。背景の三つのアーチが画面を区切り、左の兄弟、中央の父、右で嘆く女性たちが、まるで舞台のようにはっきり分けて配置されています。まっすぐ伸びた腕や脚、くっきりした輪郭は、曲線と淡い色のロココとは正反対です。個人の感情より国家への義務を重んじる主題は、フランス革命前夜の人々に強い印象を与えました。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('コルネリア、グラックス兄弟の母', 'Cornelia, Mother of the Gracchi, Pointing to Her Children as Her Treasures', 'アンゲリカ・カウフマン', 'Angelica Kauffmann',
        1785,
        (select slug from public.art_movements where slug = 'neoclassicism'),
        'ヴァージニア美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/42/Kauffmann_Cornelia_mater_Gracchorum.jpg/960px-Kauffmann_Cornelia_mater_Gracchorum.jpg', 'スイス生まれのアンゲリカ・カウフマンは、ロンドンのロイヤル・アカデミー創立時の会員に名を連ねた、数少ない女性画家の一人です。この作品は古代ローマの逸話を描いたもので、宝石を見せびらかす客の女性に対し、母コルネリアが自分の子どもたちこそが宝だと示しています。子どもたちは後に政治家となるグラックス兄弟です。簡素な室内、落ち着いた身ぶり、家庭の美徳という教訓的な主題は、新古典主義が好んだ要素をよく表しています。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('アモルの接吻で蘇るプシュケ', 'Psyche Revived by Cupid''s Kiss', 'アントニオ・カノーヴァ', 'Antonio Canova',
        1787,
        (select slug from public.art_movements where slug = 'neoclassicism'),
        'ルーヴル美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ef/0_Psych%C3%A9_ranim%C3%A9e_par_le_baiser_de_l%27Amour_-_Canova_-_Louvre_1.JPG/960px-0_Psych%C3%A9_ranim%C3%A9e_par_le_baiser_de_l%27Amour_-_Canova_-_Louvre_1.JPG', '新古典主義を代表するイタリアの彫刻家カノーヴァによる大理石像です。古代ローマの物語に登場する王女プシュケが、禁じられた箱を開けて深い眠りに落ち、恋人アモル（キューピッド）の口づけで目覚める瞬間を表しています。二人の腕と翼が大きなX字を描くように組み合わされ、どの方向から見ても美しい形になるよう工夫されています。磨き上げられた白い大理石のなめらかさは、古代彫刻の理想美を新しくよみがえらせたものとして高く評価されました。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('マラーの死', 'The Death of Marat', 'ジャック＝ルイ・ダヴィッド', 'Jacques-Louis David',
        1793,
        (select slug from public.art_movements where slug = 'neoclassicism'),
        'ベルギー王立美術館（ブリュッセル）', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f8/Jacques-Louis_David_-_Marat_assassinated_-_Google_Art_Project_2.jpg/960px-Jacques-Louis_David_-_Marat_assassinated_-_Google_Art_Project_2.jpg', 'フランス革命の指導者の一人マラーが、1793年に浴槽で暗殺された事件を、友人でもあったダヴィッドが描いた作品です。皮膚病の治療のため浴槽で仕事をしていたマラーは、手紙とペンを持ったまま息絶えています。上半分はほとんど何もない暗い壁で、その静けさが死の重さを強めています。だらりと下がった腕は、キリストの死を描いた宗教画を思わせるとよく指摘されます。古代の英雄を描く手法で、同時代の出来事を描いた点が注目されます。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('グランド・オダリスク', 'Grande Odalisque', 'ジャン＝オーギュスト＝ドミニク・アングル', 'Jean-Auguste-Dominique Ingres',
        1814,
        (select slug from public.art_movements where slug = 'neoclassicism'),
        'ルーヴル美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/df/La_grande_odalisque_-_Jean-Auguste_Dominique_Ingres_-_Mus%C3%A9e_du_Louvre_Peintures_RF_1158.jpg/960px-La_grande_odalisque_-_Jean-Auguste_Dominique_Ingres_-_Mus%C3%A9e_du_Louvre_Peintures_RF_1158.jpg', 'ダヴィッドの弟子アングルが、ナポリ王妃カロリーヌ・ミュラの注文で描いた、オスマン帝国のハーレムの女性（オダリスク）の後ろ姿です。なめらかな肌と冷たく澄んだ色調は新古典主義らしい仕上げですが、背中や腕は実際の人体よりも長く引き伸ばされています。発表当時は「背骨が数本多い」と批判されましたが、アングルは正確さよりも線の美しさを優先したのです。異国趣味の主題には、次のロマン主義に通じる関心もうかがえます。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('マドリード、1808年5月3日', 'The Third of May 1808', 'フランシスコ・デ・ゴヤ', 'Francisco Goya',
        1814,
        (select slug from public.art_movements where slug = 'romanticism'),
        'プラド美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/48/El_Tres_de_Mayo%2C_by_Francisco_de_Goya%2C_from_Prado_in_Google_Earth.jpg/960px-El_Tres_de_Mayo%2C_by_Francisco_de_Goya%2C_from_Prado_in_Google_Earth.jpg', '1808年、ナポレオン軍の占領に抵抗したマドリードの市民が、翌日フランス兵に銃殺された出来事を、ゴヤが1814年に描いた作品です。右側の兵士たちは顔が見えず、機械のように一列に並んで銃を構えています。左側では、ランタンの光を浴びた白いシャツの男が両手を広げ、まわりには死体や顔をおおう人々がいます。英雄をたたえるのではなく、名もない人々の恐怖と死を正面から描いたこの絵は、戦争を描く絵画の見方を大きく変えました。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('雲海の上の旅人', 'Wanderer above the Sea of Fog', 'カスパー・ダーヴィト・フリードリヒ', 'Caspar David Friedrich',
        1818,
        (select slug from public.art_movements where slug = 'romanticism'),
        'ハンブルク美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1e/Friedrich%2C_Caspar_David_-_Wanderer_%C3%BCber_dem_Nebelmeer.jpg/960px-Friedrich%2C_Caspar_David_-_Wanderer_%C3%BCber_dem_Nebelmeer.jpg', 'ドイツ・ロマン主義の画家フリードリヒの代表作です。岩山の頂に立つ男性が、こちらに背を向けて、霧に包まれた山々を見下ろしています。人物の顔が見えないため、見る人は男性と同じ位置から景色をながめているような気持ちになります。この「後ろ姿の人物」はフリードリヒがよく用いた工夫です。広大な自然を前にした一人の人間の孤独や、畏れ、思索といった内面の感情を、風景を通して表しており、風景画が心を描く手段になったことを示しています。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('メデューズ号の筏', 'The Raft of the Medusa', 'テオドール・ジェリコー', 'Théodore Géricault',
        1818,
        (select slug from public.art_movements where slug = 'romanticism'),
        'ルーヴル美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/15/JEAN_LOUIS_TH%C3%89ODORE_G%C3%89RICAULT_-_La_Balsa_de_la_Medusa_%28Museo_del_Louvre%2C_1818-19%29.jpg/960px-JEAN_LOUIS_TH%C3%89ODORE_G%C3%89RICAULT_-_La_Balsa_de_la_Medusa_%28Museo_del_Louvre%2C_1818-19%29.jpg', '1816年にフランスの軍艦メデューズ号が座礁し、筏で漂流した乗員の多くが亡くなった実際の事件を題材にした大作です。ジェリコーは生存者に話を聞き、筏の模型を作るなど入念に準備しました。画面は左下の死者から右上で布を振る男へと、絶望から希望へ向かうピラミッド形に組み立てられています。古代の英雄ではなく、同時代の悲劇とふつうの人々の苦しみを巨大な画面に描いたことで、1819年のサロンで大きな議論を呼びました。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('乾草の車', 'The Hay Wain', 'ジョン・コンスタブル', 'John Constable',
        1821,
        (select slug from public.art_movements where slug = 'romanticism'),
        'ロンドン・ナショナル・ギャラリー', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5e/John_Constable_-_The_Hay_Wain_%281821%29.jpg/960px-John_Constable_-_The_Hay_Wain_%281821%29.jpg', 'イギリスの画家コンスタブルが、故郷サフォーク州の川辺を描いた風景画です。馬に引かれた荷車が浅瀬を渡り、空には雲が流れています。コンスタブルは戸外で多くのスケッチを重ね、雲や光、木々の緑の変化を細かく観察しました。白い絵の具を点のように置いて、水面や葉のきらめきを表しているのも特徴です。1824年のパリのサロンに出品されると高く評価され、ドラクロワらフランスの画家にも刺激を与えました。身近な田園が絵の主役になった例です。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('民衆を導く自由の女神', 'Liberty Leading the People', 'ウジェーヌ・ドラクロワ', 'Eugène Delacroix',
        1830,
        (select slug from public.art_movements where slug = 'romanticism'),
        'ルーヴル美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/02/La_Libert%C3%A9_guidant_le_peuple_-_Eug%C3%A8ne_Delacroix_-_Mus%C3%A9e_du_Louvre_Peintures_RF_129_-_apr%C3%A8s_restauration_2024.jpg/960px-La_Libert%C3%A9_guidant_le_peuple_-_Eug%C3%A8ne_Delacroix_-_Mus%C3%A9e_du_Louvre_Peintures_RF_129_-_apr%C3%A8s_restauration_2024.jpg', '1830年のフランス七月革命を題材に、ドラクロワが同じ年に描いた作品です。三色旗を高く掲げて進む女性は「自由」を表す擬人像で、その周りにはシルクハットの市民、銃を持つ少年、倒れた兵士たちがいます。画面は斜めの動きにあふれ、煙の中で旗の赤・白・青が鮮やかに目を引きます。現実の事件と寓意の人物を一つの画面に組み合わせ、色彩と勢いで感情に訴える表現は、ロマン主義絵画を代表する作品とされ、のちにフランスの紙幣の図柄にも使われました。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('雨、蒸気、速度 – グレート・ウェスタン鉄道', 'Rain, Steam and Speed – The Great Western Railway', 'J・M・W・ターナー', 'J. M. W. Turner',
        1844,
        (select slug from public.art_movements where slug = 'romanticism'),
        'ロンドン・ナショナル・ギャラリー', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5f/J._M._W._Turner_-_Rain%2C_Steam_and_Speed_%E2%80%93_The_Great_Western_Railway.jpg/960px-J._M._W._Turner_-_Rain%2C_Steam_and_Speed_%E2%80%93_The_Great_Western_Railway.jpg', 'テムズ川にかかる鉄道橋の上を、蒸気機関車がこちらに向かって走ってくる様子を描いた作品です。雨や蒸気、光が溶け合い、形ははっきりと描かれていません。ターナーは自然の力や大気の変化を描き続けた画家で、この作品では産業革命が生んだ新しい乗り物の「速さ」そのものを表そうとしました。よく見ると、線路の先には機関車から逃げるように走る小さなウサギが描かれています。光と色だけで画面をつくる表現は、後の印象派を先取りしたとも言われます。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('オルナンの埋葬', 'A Burial at Ornans', 'ギュスターヴ・クールベ', 'Gustave Courbet',
        1849,
        (select slug from public.art_movements where slug = 'realism'),
        'オルセー美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/50/Gustave_Courbet_-_A_Burial_at_Ornans_-_Google_Art_Project.jpg/960px-Gustave_Courbet_-_A_Burial_at_Ornans_-_Google_Art_Project.jpg', 'クールベが故郷オルナン村で行われた葬儀を描いた、横幅6メートルを超える大作です。描かれているのは村の人々で、司祭や家族、喪服の女性たちが横一列に並んでいます。当時、これほど大きな画面は歴史画や宗教画のためのものでした。そこに名もない地方の人々のありふれた葬式を描いたことが、1850年から翌年にかけてのサロンで大きな反発を招きました。理想化しない顔つきや重い黒の色調に、写実主義の宣言ともいえる姿勢が表れています。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('ニヴェルネー地方の耕作', 'Ploughing in the Nivernais', 'ローザ・ボヌール', 'Rosa Bonheur',
        1849,
        (select slug from public.art_movements where slug = 'realism'),
        'オルセー美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/17/Rosa_Bonheur_-_Ploughing_in_Nevers_-_Google_Art_Project.jpg/960px-Rosa_Bonheur_-_Ploughing_in_Nevers_-_Google_Art_Project.jpg', '19世紀フランスを代表する女性画家ローザ・ボヌールが、フランス政府の注文で描き、1849年のサロンで評価された作品です。秋の畑で、牛の群れが重い鋤を引いて土を掘り起こしています。ボヌールは動物の体のつくりを学ぶため、畜産市場や食肉処理場に通って観察を重ねました。牛の筋肉や毛並み、掘り返された土の質感が丁寧に描かれ、農村の労働を明るい光の中で堂々と表しています。動物画で国際的な名声を得た彼女の代表作です。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('落穂拾い', 'The Gleaners', 'ジャン＝フランソワ・ミレー', 'Jean-François Millet',
        1857,
        (select slug from public.art_movements where slug = 'realism'),
        'オルセー美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/da/Jean-Fran%C3%A7ois_Millet_-_Des_glaneuses.jpg/960px-Jean-Fran%C3%A7ois_Millet_-_Des_glaneuses.jpg', 'パリ郊外のバルビゾン村に移り住んだミレーが、収穫の後の畑で落ちた麦の穂を拾う3人の農婦を描いた作品です。落穂拾いは、貧しい人々に認められていた暮らしの手段でした。遠くには山のように積まれた麦と収穫に働く人々が小さく見え、手前の女性たちとの対比が浮かび上がります。腰をかがめた3人の姿は、彫刻のように重々しく安定した形にまとめられています。働く人の姿を記念碑のように描いたことで、社会への問いかけとして受け止められました。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('三等客車', 'The Third-Class Carriage', 'オノレ・ドーミエ', 'Honoré Daumier',
        1862,
        (select slug from public.art_movements where slug = 'realism'),
        'メトロポリタン美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d8/Honor%C3%A9_Daumier_%28French%2C_Marseilles_1808%E2%80%931879_Valmondois%29_-_The_Third-Class_Carriage_-_Google_Art_Project.jpg/960px-Honor%C3%A9_Daumier_%28French%2C_Marseilles_1808%E2%80%931879_Valmondois%29_-_The_Third-Class_Carriage_-_Google_Art_Project.jpg', '新聞の風刺版画で知られたドーミエが、鉄道の安い三等客車に乗る人々を描いた油彩画です。手前には赤ん坊を抱く母親、かごを持つ老女、眠る少年が並び、その後ろにはぎっしりと乗客が詰め込まれています。人々は会話もなく、それぞれ疲れた表情を浮かべています。荒く素早い筆づかいと暗い色調で、近代化が進む都市の中で暮らす庶民の姿をありのままに伝えています。メトロポリタン美術館の作品は1862〜64年ごろの制作とされています。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('ヴォルガの舟曳き', 'Barge Haulers on the Volga', 'イリヤ・レーピン', 'Ilya Repin',
        1870,
        (select slug from public.art_movements where slug = 'realism'),
        'ロシア美術館（サンクトペテルブルク）', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7a/Ilya_Repin_-_Barge_Haulers_on_the_Volga_-_Google_Art_Project.jpg/960px-Ilya_Repin_-_Barge_Haulers_on_the_Volga_-_Google_Art_Project.jpg', 'ロシアの画家レーピンが、ヴォルガ川で船を綱で引いて川をさかのぼる労働者たちを描いた作品で、1873年に完成しました。照りつける日差しの中、11人の男たちが体を前に倒し、重い足どりで進んでいます。一人ひとりの顔つきや年齢、表情は描き分けられ、中央の若者だけが顔を上げているのが印象的です。レーピンは実際にヴォルガ川を訪れて取材しました。写実主義の考え方がフランスからロシアへ広がり、民衆の暮らしを描く力強い絵画を生んだことを示しています。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('オフィーリア', 'Ophelia', 'ジョン・エヴァレット・ミレー', 'John Everett Millais',
        1851,
        (select slug from public.art_movements where slug = 'pre-raphaelite'),
        'テート・ブリテン', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/94/John_Everett_Millais_-_Ophelia_-_Google_Art_Project.jpg/960px-John_Everett_Millais_-_Ophelia_-_Google_Art_Project.jpg', 'シェイクスピアの『ハムレット』で、恋人に父を殺され正気を失ったオフィーリアが、川に落ちて歌いながら沈んでいく場面です。ミレーは背景をロンドン郊外の川辺に何か月も通って描き、草花や水辺の植物を植物図鑑のような正確さで写しました。モデルは後にロセッティの妻となるエリザベス・シダルで、浴槽に浮かんでポーズをとりました。近くも遠くも同じくらい細かく描かれた画面は、自然を誠実に写すというラファエル前派の考え方をよく表しています。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('世の光', 'The Light of the World', 'ウィリアム・ホルマン・ハント', 'William Holman Hunt',
        1851,
        (select slug from public.art_movements where slug = 'pre-raphaelite'),
        'キーブル・カレッジ（オックスフォード）', 'https://upload.wikimedia.org/wikipedia/commons/0/0d/Hunt%2C_William_Homan_-_The_Light_of_the_World_-_1853-54.jpg', 'ラファエル前派の創立メンバー、ホルマン・ハントが描いたキリスト像です。ランタンを手にしたキリストが、ツタにおおわれた古い扉をノックしています。この扉には外側に取っ手がなく、内側からしか開けられないことから、人の心の扉を象徴していると説明されてきました。ハントは月明かりの効果を確かめるため、夜に戸外で制作したと伝えられています。細かな自然描写の一つひとつに宗教的な意味を込める点に、ラファエル前派らしい特徴があります。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('イギリスの見納め', 'The Last of England', 'フォード・マドックス・ブラウン', 'Ford Madox Brown',
        1852,
        (select slug from public.art_movements where slug = 'pre-raphaelite'),
        'バーミンガム美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fb/Ford_Madox_Brown_-_The_Last_of_England_-_Google_Art_Project.jpg/960px-Ford_Madox_Brown_-_The_Last_of_England_-_Google_Art_Project.jpg', '当時イギリスから多くの人がオーストラリアなどへ移民していたことを背景に、故郷を離れる船の上の夫婦を描いた作品です。モデルには画家自身と妻が務めました。丸い画面の中で、二人は冷たい風を受けながら、硬い表情で前を見つめています。妻のマントの下からは赤ん坊の小さな手がのぞいています。ブラウンはラファエル前派の正式な会員ではありませんでしたが、仲間と同じく細部まで正確に描く方法で、同時代の社会の問題を描きました。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('ベアタ・ベアトリクス', 'Beata Beatrix', 'ダンテ・ゲイブリエル・ロセッティ', 'Dante Gabriel Rossetti',
        1864,
        (select slug from public.art_movements where slug = 'pre-raphaelite'),
        'テート・ブリテン', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/aa/Dante_Gabriel_Rossetti_-_Beata_Beatrix_-_Google_Art_Project.jpg/960px-Dante_Gabriel_Rossetti_-_Beata_Beatrix_-_Google_Art_Project.jpg', '1862年に亡くなった妻エリザベス・シダルを、イタリアの詩人ダンテが愛したベアトリーチェに重ねて描いた作品です。目を閉じた女性は、死の瞬間に天上の世界へ移っていく姿として表されています。赤い鳥がくわえてきたケシの花は眠りと死を、背景の人物はダンテと愛の神を表すとされます。初期の細密な描写とは違い、ぼんやりと光に包まれた画面になっており、ロセッティの関心が夢や象徴へ向かったことがわかります。後の象徴主義にもつながる作品です。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('シャロットの女', 'The Lady of Shalott', 'ジョン・ウィリアム・ウォーターハウス', 'John William Waterhouse',
        1888,
        (select slug from public.art_movements where slug = 'pre-raphaelite'),
        'テート・ブリテン', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/68/John_William_Waterhouse_-_The_Lady_of_Shalott_-_Google_Art_Project_%28derivative_work_-_AutoContrast_edit_in_LCH_space%29.jpg/960px-John_William_Waterhouse_-_The_Lady_of_Shalott_-_Google_Art_Project_%28derivative_work_-_AutoContrast_edit_in_LCH_space%29.jpg', 'テニスンの詩に登場する、塔の中で鏡越しにしか外の世界を見られない呪いを受けた女性が、塔を出て小舟で川を下っていく場面です。ウォーターハウスはラファエル前派の結成より後の世代の画家ですが、アーサー王伝説や文学を題材にする点でその流れを受け継いでいます。一方、背景の草木や水面の描き方には、フランスの戸外制作の影響も見られます。舟の上のろうそくや、歌を口ずさむようにわずかに開いた口元に、悲劇の結末が暗示されています。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('草上の昼食', 'Luncheon on the Grass', 'エドゥアール・マネ', 'Édouard Manet',
        1863,
        (select slug from public.art_movements where slug = 'impressionism'),
        'オルセー美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/90/Edouard_Manet_-_Luncheon_on_the_Grass_-_Google_Art_Project.jpg/960px-Edouard_Manet_-_Luncheon_on_the_Grass_-_Google_Art_Project.jpg', '1863年のサロンに落選し、同じ年の「落選展」で大きなスキャンダルとなった作品です。森の中で、同時代の服を着た男性二人と裸の女性がくつろいでいます。裸婦は神話の中の女神なら許されましたが、現実のパリの女性として描かれ、しかもこちらを平然と見つめていることが人々を驚かせました。陰影をおさえた平らな塗り方も批判されました。マネ自身は印象派展に参加しませんでしたが、この作品はモネら若い画家たちに大きな刺激を与えました。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('印象・日の出', 'Impression, Sunrise', 'クロード・モネ', 'Claude Monet',
        1872,
        (select slug from public.art_movements where slug = 'impressionism'),
        'マルモッタン・モネ美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/59/Monet_-_Impression%2C_Sunrise.jpg/960px-Monet_-_Impression%2C_Sunrise.jpg', 'モネが故郷に近いル・アーヴルの港で、朝もやの中に昇る太陽を描いた作品です。1874年の第1回のグループ展に出品され、批評家がこの題名をもじって画家たちを「印象派」と呼んだことで知られます。港のクレーンや船は数本の筆跡で表されるだけで、細かな描写はありません。そのかわり、オレンジ色の太陽と水面に映る光が、灰青色の空気の中で浮かび上がります。物の形よりも、その瞬間の光と空気の「印象」を描こうとした、印象派の出発点となる作品です。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('ゆりかご', 'The Cradle', 'ベルト・モリゾ', 'Berthe Morisot',
        1872,
        (select slug from public.art_movements where slug = 'impressionism'),
        'オルセー美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/eb/Berthe_Morisot_-_Le_berceau.jpg/960px-Berthe_Morisot_-_Le_berceau.jpg', '印象派の中心メンバーの一人だった女性画家ベルト・モリゾが、姉エドマと、ゆりかごで眠るその娘を描いた作品です。1874年の第1回のグループ展にも出品されました。母親はゆりかごの薄い布越しに、頬杖をついて子どもを見守っています。白いレースのとばりは、透ける軽さを生かした柔らかな筆づかいで描かれています。当時の女性画家は自由に街を出歩いて描くことが難しかったため、モリゾは家庭の中の親密な時間を主題とし、印象派の新しい表現で描きました。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('アブサントを飲む人', 'L''Absinthe', 'エドガー・ドガ', 'Edgar Degas',
        1875,
        (select slug from public.art_movements where slug = 'impressionism'),
        'オルセー美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e8/Edgar_Degas_-_In_a_Caf%C3%A9_-_Google_Art_Project_2.jpg/960px-Edgar_Degas_-_In_a_Caf%C3%A9_-_Google_Art_Project_2.jpg', 'パリのカフェで、強い酒アブサントのグラスを前にぼんやり座る女性と、パイプをくわえた男性を描いた作品です。モデルは女優のエレン・アンドレと画家マルスラン・デブータンでした。人物は画面の右上に寄せられ、手前にはテーブルが斜めに大きく広がっています。この偶然切り取ったような構図には、写真や日本の浮世絵からの影響が指摘されています。光の移ろいよりも都市に生きる人々の孤独を見つめた点に、印象派の中でもドガらしい個性が表れています。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('ムーラン・ド・ラ・ギャレットの舞踏会', 'Bal du moulin de la Galette', 'ピエール＝オーギュスト・ルノワール', 'Pierre-Auguste Renoir',
        1876,
        (select slug from public.art_movements where slug = 'impressionism'),
        'オルセー美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6f/Renoir%2C_Pierre-Auguste_-_Dance_at_Le_Moulin_de_la_Galette%2C_1876.jpg/960px-Renoir%2C_Pierre-Auguste_-_Dance_at_Le_Moulin_de_la_Galette%2C_1876.jpg', 'パリのモンマルトルにあった野外のダンスホールで、日曜日の午後を楽しむ人々を描いた作品です。ルノワールの友人たちもモデルとして登場しています。木の葉の間からこぼれる日の光が、人々の服や顔、地面にまだらな明るい点となって散らばっています。影は黒ではなく青や紫で描かれ、画面全体がきらめくような明るさに満ちています。特別な出来事ではなく、都市に暮らす人々のありふれた楽しみを主題にしたところに、印象派の新しさがあります。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('湯浴み', 'The Child''s Bath', 'メアリー・カサット', 'Mary Cassatt',
        1893,
        (select slug from public.art_movements where slug = 'impressionism'),
        'シカゴ美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f5/The_Child%27s_Bath_by_Mary_Cassatt_1893.jpg/960px-The_Child%27s_Bath_by_Mary_Cassatt_1893.jpg', 'アメリカ出身でパリに住み、ドガに誘われて印象派展に参加したメアリー・カサットの作品です。母親が膝の上の幼い子どもの足を洗っており、二人は同じ方向に視線を落としています。画面は上から見下ろすような高い視点で描かれ、床の模様や水差し、ストライプの服が平らな色面としてくっきり表されています。1890年にパリで開かれた日本の版画の展覧会に強く刺激を受けたカサットは、浮世絵の構図や輪郭の考え方を自分の作品に取り入れました。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('グランド・ジャット島の日曜日の午後', 'A Sunday Afternoon on the Island of La Grande Jatte', 'ジョルジュ・スーラ', 'Georges Seurat',
        1884,
        (select slug from public.art_movements where slug = 'post-impressionism'),
        'シカゴ美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7d/A_Sunday_on_La_Grande_Jatte%2C_Georges_Seurat%2C_1884.jpg/960px-A_Sunday_on_La_Grande_Jatte%2C_Georges_Seurat%2C_1884.jpg', 'パリ郊外のセーヌ川の中州で休日を過ごす人々を描いた、横幅3メートルほどの大作です。スーラは色の理論を研究し、絵の具をパレットで混ぜずに小さな色の点を並べ、見る人の目の中で色が混ざり合うようにする「点描法」で描きました。題材は印象派と同じ都市の行楽ですが、人物は彫刻のように静止し、画面は綿密に計算されて構成されています。1886年の最後の印象派展に出品され、印象派の後の新しい方向を示す作品となりました。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('タンギー爺さん', 'Portrait of Père Tanguy', 'フィンセント・ファン・ゴッホ', 'Vincent van Gogh',
        1887,
        (select slug from public.art_movements where slug = 'post-impressionism'),
        'ロダン美術館（パリ）', 'https://upload.wikimedia.org/wikipedia/commons/5/5f/Van_Gogh_-_Portrait_of_Pere_Tanguy_1887-8.JPG', 'パリで画材店を営み、貧しい画家たちを支えたジュリアン・タンギーを描いた肖像画です。背景の壁には、富士山や着物姿の人物など、ゴッホが集めていた日本の浮世絵が隙間なく描き込まれています。ゴッホはパリ時代に浮世絵を熱心に集め、模写もしており、はっきりした輪郭や明るく平らな色面をそこから学びました。正面を向いて手を組んで座る素朴なタンギーの姿は、浮世絵の世界の中に置かれているようです。ジャポニスムの影響がよくわかる作品です。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('星月夜', 'The Starry Night', 'フィンセント・ファン・ゴッホ', 'Vincent van Gogh',
        1889,
        (select slug from public.art_movements where slug = 'post-impressionism'),
        'ニューヨーク近代美術館（MoMA）', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ea/Van_Gogh_-_Starry_Night_-_Google_Art_Project.jpg/960px-Van_Gogh_-_Starry_Night_-_Google_Art_Project.jpg', '南フランスのサン＝レミにある療養院に入っていた時期に、ゴッホが描いた夜の風景です。夜空には大きな渦が流れ、星や月は光の輪に包まれて輝いています。手前には炎のような形の糸杉がそびえ、下には静かな村が広がっています。目に見えるとおりに描くのではなく、うねるような筆づかいと強い色で、画家自身の感情や想像を画面にあふれさせています。印象派から出発しながら、色と形を感情の表現に使ったこの方法は、後の表現主義にも大きな影響を与えました。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('ムーラン・ルージュにて', 'At the Moulin Rouge', 'アンリ・ド・トゥールーズ＝ロートレック', 'Henri de Toulouse-Lautrec',
        1892,
        (select slug from public.art_movements where slug = 'post-impressionism'),
        'シカゴ美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/10/Henri_de_Toulouse-Lautrec_-_At_the_Moulin_Rouge_-_1928.610_-_Art_Institute_of_Chicago.jpg/960px-Henri_de_Toulouse-Lautrec_-_At_the_Moulin_Rouge_-_1928.610_-_Art_Institute_of_Chicago.jpg', 'パリのモンマルトルにあったキャバレー「ムーラン・ルージュ」の店内を描いた作品で、1892年から95年ごろにかけて制作されました。テーブルを囲む客たちの奥には、背の低いロートレック自身の姿も描かれています。右手前の女性の顔は、照明を受けて緑色に不気味に光っています。手すりが画面を斜めに横切り、人物が画面の端で大胆に切られる構図には、ドガや浮世絵の影響が見られます。夜の娯楽の華やかさとその裏の疲れや孤独を、鋭い観察で描いています。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('りんごの籠のある静物', 'The Basket of Apples', 'ポール・セザンヌ', 'Paul Cézanne',
        1893,
        (select slug from public.art_movements where slug = 'post-impressionism'),
        'シカゴ美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/38/Paul_C%C3%A9zanne_-_The_Basket_of_Apples_-_1926.252_-_Art_Institute_of_Chicago.jpg/960px-Paul_C%C3%A9zanne_-_The_Basket_of_Apples_-_1926.252_-_Art_Institute_of_Chicago.jpg', 'テーブルの上に、傾いた籠からこぼれそうなりんご、ワインの瓶、皿に積まれたビスケットが置かれた静物画です。よく見ると、瓶は傾き、テーブルの手前の縁は左右で高さがずれています。セザンヌは一つの視点から見た正確な姿ではなく、少しずつ違う角度から見た形を組み合わせて、画面全体の安定とまとまりをつくろうとしました。印象派の明るい色を受け継ぎつつ、物のしっかりした形と構成を取り戻そうとしたこの試みは、後のキュビスムに大きな影響を与えました。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('我々はどこから来たのか 我々は何者か 我々はどこへ行くのか', 'Where Do We Come From? What Are We? Where Are We Going?', 'ポール・ゴーギャン', 'Paul Gauguin',
        1897,
        (select slug from public.art_movements where slug = 'post-impressionism'),
        'ボストン美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0a/Gauguin_-_Where_Do_We_Come_From%3F_What_Are_We%3F_Where_Are_We_Going%3F_%281897-98%29.jpg/960px-Gauguin_-_Where_Do_We_Come_From%3F_What_Are_We%3F_Where_Are_We_Going%3F_%281897-98%29.jpg', '文明社会を離れて南太平洋のタヒチに渡ったゴーギャンが、1897年から98年にかけて描いた横長の大作です。題名は画面の左上に書き込まれています。右端の赤ん坊から、中央で果実をもぐ若者、左端でうずくまる老女へと、右から左に人の一生が流れるように読めると、画家自身が説明しています。現実の空間よりも、平らな色面と力強い輪郭、象徴的な人物や像の配置で、生と死の問いを表そうとしており、象徴主義にも近い作品です。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('出現', 'The Apparition', 'ギュスターヴ・モロー', 'Gustave Moreau',
        1876,
        (select slug from public.art_movements where slug = 'symbolism'),
        'オルセー美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/23/Gustave_Moreau_-_The_Apparition_-_Google_Art_Project.jpg/960px-Gustave_Moreau_-_The_Apparition_-_Google_Art_Project.jpg', '新約聖書に登場するサロメの物語を題材にした水彩画で、1876年のサロンに出品されました。踊り終えたサロメの前に、光を放つ洗礼者ヨハネの首が空中に現れ、サロメはそれを指さしています。周りの人々にはこの幻が見えていないようで、サロメの内面の世界に現れたものとも読めます。背景の宮殿には細い線で模様がびっしりと描き込まれ、宝石のような装飾性を生んでいます。現実ではない幻想と官能を描いたこの作品は、象徴主義の文学者たちにも強い印象を与えました。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('死の島', 'Isle of the Dead', 'アルノルト・ベックリン', 'Arnold Böcklin',
        1880,
        (select slug from public.art_movements where slug = 'symbolism'),
        'バーゼル市立美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/65/Arnold_B%C3%B6cklin_-_Die_Toteninsel_III_%28Alte_Nationalgalerie%2C_Berlin%29.jpg/960px-Arnold_B%C3%B6cklin_-_Die_Toteninsel_III_%28Alte_Nationalgalerie%2C_Berlin%29.jpg', 'スイスの画家ベックリンが描いた、暗い海に浮かぶ岩の小島の絵です。島には黒々とした糸杉が茂り、岩には墓所のような入口が刻まれています。手前の小舟には白い布をまとった人物と、白い布におおわれた棺のようなものが乗り、島へ静かに近づいています。ベックリンはこの主題で5点の作品を描いており、バーゼルの作品はその最初のものです。物語ははっきり語られず、死や静けさへの思いを見る人に呼び起こす作品として、20世紀初めまで広く愛されました。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('貧しき漁夫', 'The Poor Fisherman', 'ピエール・ピュヴィス・ド・シャヴァンヌ', 'Pierre Puvis de Chavannes',
        1881,
        (select slug from public.art_movements where slug = 'symbolism'),
        'オルセー美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/62/Pierre_Puvis_de_Chavannes_-_The_Poor_Fisherman_-_Google_Art_Project.jpg/960px-Pierre_Puvis_de_Chavannes_-_The_Poor_Fisherman_-_Google_Art_Project.jpg', '公共建築の壁画で知られたピュヴィス・ド・シャヴァンヌの作品で、1881年のサロンに出品されました。小舟の上でうつむいて立つ漁師と、岸辺で花を摘む少女、草の上に寝かされた赤ん坊が描かれています。色は灰色がかった淡い調子に抑えられ、人物や風景は奥行きの少ない平らな形で表されています。何が起きているかを語るよりも、貧しさや祈り、静かな悲しみといった感情を全体で伝えようとしています。この簡素で装飾的な画面は、後の若い画家たちからも注目されました。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('私は私自身に扉を閉ざす', 'I lock my door upon myself', 'フェルナン・クノップフ', 'Fernand Khnopff',
        1891,
        (select slug from public.art_movements where slug = 'symbolism'),
        'ノイエ・ピナコテーク（ミュンヘン）', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3c/I_lock_my_door_upon_myself_Fernand_Khnopff_1891.jpg/960px-I_lock_my_door_upon_myself_Fernand_Khnopff_1891.jpg', 'ベルギーの象徴主義を代表するクノップフの作品です。題名は、ラファエル前派のロセッティの妹で詩人のクリスティーナ・ロセッティの詩の一節から取られています。頬杖をついた女性が、遠くを見つめるように宙を見つめています。背後には眠りの神ヒュプノスの頭部の像や、ユリの花などが置かれ、外の世界を遠ざけ、自分の内面にこもる心の状態が暗示されています。はっきりした物語のないまま、静かな不安を感じさせる、象徴主義らしい作品です。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('ユディトI', 'Judith I', 'グスタフ・クリムト', 'Gustav Klimt',
        1901,
        (select slug from public.art_movements where slug = 'symbolism'),
        'ベルヴェデーレ宮殿オーストリア絵画館（ウィーン）', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e2/Judith_1_%28cropped%29.jpg/960px-Judith_1_%28cropped%29.jpg', 'ウィーンの画家クリムトが、旧約聖書外典のユディトを描いた作品です。敵将ホロフェルネスの首を手にしたユディトは、目を半ば閉じ、恍惚とした表情を浮かべています。17世紀のアルテミジア・ジェンティレスキが行動する女性として描いたのとは違い、クリムトは男性を破滅させる魅惑的な女性、いわゆる「宿命の女」として表しました。背景や首飾りには金が使われ、平面的な装飾と写実的な顔の対比が印象的です。象徴主義とアール・ヌーヴォーをつなぐ作品といえます。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('キュクロプス', 'The Cyclops', 'オディロン・ルドン', 'Odilon Redon',
        1914,
        (select slug from public.art_movements where slug = 'symbolism'),
        'クレラー・ミュラー美術館（オッテルロー）', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/be/Odilon_Redon_-_The_Cyclops%2C_c._1914.jpg/960px-Odilon_Redon_-_The_Cyclops%2C_c._1914.jpg', '若いころは黒い木炭画や版画で不思議な世界を描いたルドンが、晩年に色彩を取り入れて描いた作品です。ギリシャ神話で、一つ目の巨人ポリュペモスが、花の咲く斜面に眠る海の精ガラテイアを、山の向こうから恋い慕うように見つめています。怪物はおそろしい姿ではなく、どこか内気で悲しげに描かれています。花のように柔らかい色彩は現実の風景ではなく夢の中の光景のようです。目に見えないものを想像力で描く、象徴主義の魅力がよく表れています。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('ムーラン・ルージュ、ラ・グーリュ', 'Moulin Rouge: La Goulue', 'アンリ・ド・トゥールーズ＝ロートレック', 'Henri de Toulouse-Lautrec',
        1891,
        (select slug from public.art_movements where slug = 'art-nouveau'),
        'メトロポリタン美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/37/Henri_de_Toulouse-Lautrec_049.jpg/960px-Henri_de_Toulouse-Lautrec_049.jpg', 'キャバレー「ムーラン・ルージュ」のために作られた、ロートレックの初めてのポスターです。中央では人気の踊り子ラ・グーリュが脚を上げて踊り、手前には相方の踊り手が黒い影のようなシルエットで大きく描かれています。奥の観客も黒一色の平らな形で表されています。輪郭線と平らな色面、大胆な配置は、浮世絵から学んだものとされています。街頭に貼られて多くの人の目に触れたこの作品は、ポスターが芸術になる時代の始まりを告げ、続くアール・ヌーヴォーのポスターの流行につながりました。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('ジスモンダ', 'Gismonda', 'アルフォンス・ミュシャ', 'Alphonse Mucha',
        1894,
        (select slug from public.art_movements where slug = 'art-nouveau'),
        'プラハ国立美術館', 'https://upload.wikimedia.org/wikipedia/commons/2/2f/Alfons_Mucha_-_1894_-_Gismonda.jpg', '女優サラ・ベルナールが主演する舞台『ジスモンダ』のためのポスターで、1895年1月1日にパリの街に貼り出されて評判になりました。縦に長い画面いっぱいに、ヤシの葉を持つビザンティン風の衣装のベルナールが等身大近くで描かれています。頭の後ろには半円のアーチがあり、周りの文字や模様まで一つのデザインとして整えられています。このポスターをきっかけに、無名だったミュシャはベルナールと契約を結び、アール・ヌーヴォーを代表するデザイナーとして知られるようになりました。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('メディア', 'Médée', 'アルフォンス・ミュシャ', 'Alphonse Mucha',
        1898,
        (select slug from public.art_movements where slug = 'art-nouveau'),
        'ニューヨーク近代美術館（MoMA）', 'https://upload.wikimedia.org/wikipedia/commons/c/c6/Medee_1898.jpg', 'サラ・ベルナールがパリのルネサンス座で演じたギリシャ悲劇『メディア』のためのポスターです。裏切った夫への復讐のため、自分の子を殺めたメディアが、血に染まった短剣を手に、大きく目を見開いて立っています。足元には倒れた子どもの体が見えます。腕に巻かれた蛇の形の腕輪は、このポスターをもとに宝飾家ジョルジュ・フーケが実際に制作したことでも知られます。悲劇的な主題を、装飾的な線と抑えた色でまとめた、ミュシャの演劇ポスターの代表作の一つです。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('アデーレ・ブロッホ＝バウアーの肖像 I', 'Portrait of Adele Bloch-Bauer I', 'グスタフ・クリムト', 'Gustav Klimt',
        1907,
        (select slug from public.art_movements where slug = 'art-nouveau'),
        'ノイエ・ギャラリー（ニューヨーク）', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/18/Gustav_Klimt%2C_1907%2C_Adele_Bloch-Bauer_I%2C_Neue_Galerie_New_York.jpg/960px-Gustav_Klimt%2C_1907%2C_Adele_Bloch-Bauer_I%2C_Neue_Galerie_New_York.jpg', 'ウィーンの実業家の妻アデーレ・ブロッホ＝バウアーを描いた肖像画で、クリムトが金箔を多く用いた「黄金様式」の時期の代表作です。顔と手は写実的に描かれていますが、ドレスや椅子、背景は渦巻きや目のような模様で埋めつくされ、人物と装飾が溶け合っています。こうした平面的な装飾には、ビザンティンのモザイクや日本の工芸の影響も指摘されています。第二次世界大戦中にナチスに奪われ、後に遺族への返還をめぐる裁判で広く知られるようになりました。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('接吻', 'The Kiss', 'グスタフ・クリムト', 'Gustav Klimt',
        1907,
        (select slug from public.art_movements where slug = 'art-nouveau'),
        'ベルヴェデーレ宮殿オーストリア絵画館（ウィーン）', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/40/The_Kiss_-_Gustav_Klimt_-_Google_Cultural_Institute.jpg/960px-The_Kiss_-_Gustav_Klimt_-_Google_Cultural_Institute.jpg', '花の咲く崖の上で抱き合う男女を描いた、クリムトの「黄金様式」を代表する作品です。正方形の画面の中で、二人は金色の大きな衣に包まれて一つの形になっています。男性の衣には黒と白の四角い模様、女性の衣には丸や花の模様が使われ、男女の違いが装飾で表されています。顔と手だけが写実的に描かれ、ほかは平らな模様で埋められています。ウィーン分離派を率いたクリムトが、絵画と工芸の境をこえて追求した装飾性が、最も美しく結実した一枚です。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('帽子の女', 'Woman with a hat', 'アンリ・マティス', 'Henri Matisse',
        1905,
        (select slug from public.art_movements where slug = 'fauvism'),
        'サンフランシスコ近代美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fb/Matisse-Woman-with-a-Hat.jpg/960px-Matisse-Woman-with-a-Hat.jpg', 'モデルは画家の妻アメリー。1905年のサロン・ドートンヌに出品され、「野獣」という言葉が生まれるきっかけになった一枚です。顔には緑や紫、帽子や背景には赤や青緑が、混ぜずに勢いよく置かれています。肌の色を正しく写すことより、色どうしのぶつかり合いで人物の存在感を出そうとしているのがわかります。会場では非難も受けましたが、作品はスタイン家の兄妹に買われました。印象派から続く「明るい色」を、物の色から完全に自由にした出発点として見てみてください。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('緑のすじ（マティス夫人の肖像）', 'The Green Stripe', 'アンリ・マティス', 'Henri Matisse',
        1905,
        (select slug from public.art_movements where slug = 'fauvism'),
        'デンマーク国立美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/55/La_Raie_verte%2C_par_Henri_Matisse.jpg/960px-La_Raie_verte%2C_par_Henri_Matisse.jpg', '《帽子の女》と同じ1905年に描かれた、妻アメリーの肖像です。額から鼻、あごへと、顔のまん中に一本の緑の帯が通っています。顔の左右は黄みがかった色とピンクに塗り分けられ、背景も赤、緑、紫の大きな面に分かれています。ふつうなら影で表す立体感を、隣り合う色の違いだけで作っているのが見どころです。小さな画面ですが、色の面で絵を組み立てるというマティスの考えがはっきり表れ、のちの切り紙絵まで続く「色と面」の探究の原点ともいえる作品です。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('生きる喜び', 'The Joy of Life', 'アンリ・マティス', 'Henri Matisse',
        1906,
        (select slug from public.art_movements where slug = 'fauvism'),
        'バーンズ財団', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b0/La_Joie_de_vivre%2C_par_Henri_Matisse.jpg/960px-La_Joie_de_vivre%2C_par_Henri_Matisse.jpg', '1906年のアンデパンダン展に出品された大作です。木々に囲まれた明るい野原で、人々が横たわり、音楽を奏で、輪になって踊っています。フォーヴィスムの強い色はそのままに、うねるような輪郭線で人物と風景がゆったりとつながっています。古くから描かれてきた「黄金時代」や楽園の主題を、新しい色と線で描き直した作品といえます。奥に描かれた踊りの輪は、のちの代表作《ダンス》へと発展しました。画面全体をめぐる線のリズムを目で追うと、題名どおりの軽やかさが感じられます。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('コリウールの山々', 'Mountains at Collioure', 'アンドレ・ドラン', 'André Derain',
        1905,
        (select slug from public.art_movements where slug = 'fauvism'),
        'ナショナル・ギャラリー・オブ・アート（ワシントン）', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1c/Montagnes_%C3%A0_Collioure%2C_par_Andr%C3%A9_Derain.jpg/960px-Montagnes_%C3%A0_Collioure%2C_par_Andr%C3%A9_Derain.jpg', '1905年の夏、ドランは南フランスの港町コリウールでマティスと一緒に制作しました。この絵では、木の幹がサンゴのような赤、草が黄緑、山がオレンジや青の平らな面で描かれています。平行に並ぶ長い筆の跡が、画面に勢いのあるリズムを生んでいます。二人がこの夏に試した色づかいは、秋のサロン・ドートンヌで「野獣」と呼ばれることになりました。南仏の強い光を、写すのではなく色の強さに置きかえた作品として味わってみてください。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('チャリング・クロス橋', 'Pont de Charing Cross', 'アンドレ・ドラン', 'André Derain',
        1906,
        (select slug from public.art_movements where slug = 'fauvism'),
        'オルセー美術館', 'https://upload.wikimedia.org/wikipedia/commons/5/5d/Pont_de_Charing_Cross%2C_par_Andr%C3%A9_Derain.jpg', '画商ヴォラールのすすめでロンドンに滞在したドランが、テムズ川を描いた連作の一枚です。テムズ川の橋や霧は、少し前にモネが繰り返し描いた主題でした。モネが霧に溶ける光を細かな筆で追ったのに対し、ドランは川を緑や青、空を黄色やピンクの大きな色面にして、くっきりとした筆の跡で描いています。同じ場所を描いても、印象派とフォーヴィスムでは目指すものが違うことがよくわかります。水面に置かれた色の帯と、筆の向きの違いにも注目です。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('旗で飾られた通り', 'Street Decked with Flags', 'ラウル・デュフィ', 'Raoul Dufy',
        1906,
        (select slug from public.art_movements where slug = 'fauvism'),
        'ポンピドゥー・センター（国立近代美術館）', 'https://upload.wikimedia.org/wikipedia/commons/4/40/La_Rue_pavois%C3%A9e.jpg', '1906年の夏、故郷ル・アーヴルで、デュフィは友人アルベール・マルケと並んで、祝日のために旗で飾られた通りを描きました。画面いっぱいに青・白・赤の三色旗がはためき、その下を人々が歩いています。旗の色は陰影なしで平らに塗られ、通行人の一部は旗の青に溶け込むように描かれています。同じ年のサロン・ドートンヌに出品された作品です。のちに軽やかな線と色で人気を集めるデュフィが、フォーヴィスムの色に出会った時期の一枚として見ると、その後の画風とのつながりも楽しめます。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('叫び', 'The Scream', 'エドヴァルド・ムンク', 'Edvard Munch',
        1893,
        (select slug from public.art_movements where slug = 'expressionism'),
        'ノルウェー国立美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f4/The_Scream.jpg/960px-The_Scream.jpg', '夕暮れの橋の上で、両手で顔をはさんだ人物が立ちつくしています。ムンクは、夕日を見ていたときに自然を貫く叫びを感じた体験をもとにしたと書き残しています。空は赤くうねり、風景全体が人物の不安に合わせてゆがんでいます。見えたものではなく「感じたこと」を形と色で表すこの考え方は、表現主義の先駆けとして、のちのドイツの画家たちに大きな影響を与えました。ムンクは同じ主題で絵や版画など複数の版を残しており、これは厚紙に描かれた1893年の作品です。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('ベルリンの街路', 'Street, Berlin', 'エルンスト・ルートヴィヒ・キルヒナー', 'Ernst Ludwig Kirchner',
        1913,
        (select slug from public.art_movements where slug = 'expressionism'),
        'ニューヨーク近代美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/60/Ernst_Ludwig_Kirchner%2C_1913%2C_Street%2C_Berlin%2C_oil_on_canvas%2C_120.6_x_91.1_cm%2C_MoMA.jpg/960px-Ernst_Ludwig_Kirchner%2C_1913%2C_Street%2C_Berlin%2C_oil_on_canvas%2C_120.6_x_91.1_cm%2C_MoMA.jpg', 'ブリュッケの中心人物キルヒナーは、1911年にドレスデンからベルリンへ移り、大都会の通りを描く連作を始めました。この作品では、派手な帽子と毛皮をまとった女性たちと、黒い服の男たちが、細長くとがった姿で通りを埋めています。人物は互いに近いのに視線は合わず、人ごみの中の孤独や緊張が伝わってきます。木版画を思わせる鋭い線や、画面全体の傾きに注目してください。ブリュッケは同じ1913年に解散しており、グループ時代の終わりと都市の時代の始まりを感じさせる一枚です。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('青い馬I', 'Blue Horse I', 'フランツ・マルク', 'Franz Marc',
        1911,
        (select slug from public.art_movements where slug = 'expressionism'),
        'レンバッハハウス美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8b/Franz_Marc_Blaues_Pferd_1911.jpg/960px-Franz_Marc_Blaues_Pferd_1911.jpg', '1911年、マルクはカンディンスキーとともに「青騎士」を始めました。この絵では、若い馬が青一色で描かれ、背景の山々は赤や黄、緑の色面になっています。マルクは色に意味を持たせようとし、友人マッケへの手紙で、青を精神的なものと結びつけて語っています。動物を選んだのは、人間よりも純粋な存在として自然とのつながりを表したかったからだといわれます。現実の馬の色から離れても、色そのものが気持ちを伝えることを示した作品です。マルクは1916年、第一次世界大戦で戦死しました。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('コンポジションVII', 'Composition VII', 'ワシリー・カンディンスキー', 'Wassily Kandinsky',
        1913,
        (select slug from public.art_movements where slug = 'expressionism'),
        'トレチャコフ美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/01/Composition_VII_-_Wassily_Kandinsky%2C_GAC.jpg/960px-Composition_VII_-_Wassily_Kandinsky%2C_GAC.jpg', '青騎士を率いたカンディンスキーが、第一次世界大戦の前年に描いた大作で、横幅は約3メートルあります。たくさんの下絵を重ねたうえで完成させました。画面には、はっきりした物の形がほとんどなく、色の渦と線が渦巻いています。カンディンスキーは、音楽が音だけで心を動かすように、絵も色と形だけで心に響くと考えました。表現主義の「内面を表す」という考えを、具体的なものを描かない抽象にまで押し進めた作品です。中心から外へ広がる動きを、音楽を聴くように目でたどってみてください。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('死と乙女', 'Death and the Maiden', 'エゴン・シーレ', 'Egon Schiele',
        1915,
        (select slug from public.art_movements where slug = 'expressionism'),
        'ベルヴェデーレ宮殿美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/01/Egon_Schiele_-_Tod_und_M%C3%A4dchen_-_3171_-_%C3%96sterreichische_Galerie_Belvedere.jpg/960px-Egon_Schiele_-_Tod_und_M%C3%A4dchen_-_3171_-_%C3%96sterreichische_Galerie_Belvedere.jpg', '荒れた地面の上で、暗い衣をまとった男と女が抱き合っています。男は死の姿に、女はしがみつく乙女に重ねられ、シーレ自身と、長く付き合った恋人ヴァリをモデルにしていると考えられています。1915年、シーレはヴァリと別れ、別の女性と結婚しました。骨ばった手足や、ふたりの体のぎこちない角度に、別れの痛みと不安がにじみます。ウィーンでクリムトの装飾的な美しさを学んだシーレが、より生々しい感情表現へ向かったことがわかる作品です。シーレは1918年、28歳で亡くなりました。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('パブロ・ピカソの肖像', 'Portrait of Pablo Picasso', 'フアン・グリス', 'Juan Gris',
        1912,
        (select slug from public.art_movements where slug = 'cubism'),
        'シカゴ美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/18/Juan_Gris_-_Portrait_of_Pablo_Picasso_-_Google_Art_Project.jpg/960px-Juan_Gris_-_Portrait_of_Pablo_Picasso_-_Google_Art_Project.jpg', 'スペイン出身のグリスが、同郷の先輩ピカソに捧げた肖像で、1912年のアンデパンダン展で発表されました。顔や体は斜めの線で区切られた多くの面に分けられ、それぞれの面に光の当たり方が描き分けられています。手にはパレットを持ち、画家であることが示されています。ピカソとブラックが始めたキュビスムを、グリスはより整理された、幾何学的で明快な構成に変えていきました。分解されていても人物の姿が読み取りやすいので、キュビスムの入門にもおすすめの一枚です。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('チェックのテーブルクロスのある静物', 'Still Life with Checked Tablecloth', 'フアン・グリス', 'Juan Gris',
        1915,
        (select slug from public.art_movements where slug = 'cubism'),
        'メトロポリタン美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fa/Juan_Gris_-_Nature_morte_%C3%A0_la_nappe_%C3%A0_carreaux.jpg/960px-Juan_Gris_-_Nature_morte_%C3%A0_la_nappe_%C3%A0_carreaux.jpg', '1915年の春にパリで描かれた、テーブルの上の静物画です。油絵具と鉛筆で、チェック模様の布やテーブルの上の品々が、色鮮やかな平らな面として組み合わされています。初期キュビスムの茶色や灰色の画面とは違い、明るい色と、模様のような面の重なりが目立ちます。これは、紙を貼るパピエ・コレの経験を絵画に生かした「総合的キュビスム」の特徴です。どの面がテーブルの上から見た形で、どの面が横から見た形なのかを探しながら見ると、グリスの組み立ての巧みさが感じられます。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('森の中の裸体', 'Nudes in the forest', 'フェルナン・レジェ', 'Fernand Léger',
        1910,
        (select slug from public.art_movements where slug = 'cubism'),
        'クレラー・ミュラー美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fd/Fernand_L%C3%A9ger%2C_1910%2C_Nudes_in_the_forest_%28Nus_dans_la_for%C3%AAt%29%2C_oil_on_canvas%2C_120_x_170_cm%2C_Kr%C3%B6ller-M%C3%BCller_Museum.jpg/960px-Fernand_L%C3%A9ger%2C_1910%2C_Nudes_in_the_forest_%28Nus_dans_la_for%C3%AAt%29%2C_oil_on_canvas%2C_120_x_170_cm%2C_Kr%C3%B6ller-M%C3%BCller_Museum.jpg', '森で木を切る人々を描いた作品ですが、人も木も、筒や円錐のような金属的な形の集まりになっていて、どこに誰がいるのか探すのが難しいほどです。色は灰色や緑に抑えられています。1911年のアンデパンダン展に出品されると、そのチューブのような形から「チュービスム」とからかわれました。セザンヌの「自然を円筒や球でとらえる」考えを、レジェは極端に押し進めたのです。ここで生まれた機械のような形は、のちの《都市》など、近代の都市と機械を描く作品へつながっていきます。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('シャン・ド・マルス、赤い塔', 'Champs de Mars, the Red Tower', 'ロベール・ドローネー', 'Robert Delaunay',
        1911,
        (select slug from public.art_movements where slug = 'cubism'),
        'シカゴ美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3e/Delaunay_ChampDeMars.jpg/960px-Delaunay_ChampDeMars.jpg', 'ドローネーは1909年ごろから、パリのエッフェル塔を何度も描きました。この作品では赤い塔が、まわりの建物や雲とともに、折れ曲がり、砕けるように描かれています。下から見上げる視点や横からの視点が重なり、近代的な鉄の塔の高さや揺れ動く印象が伝わってきます。キュビスムの分解する方法に、明るい色と動きの感覚を加えたドローネーは、やがて色の円がめぐる抽象へと進み、詩人アポリネールはその方向を「オルフィスム」と呼びました。キュビスムが色彩の方向へ広がっていく様子がわかる作品です。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('収穫物の脱穀', 'Harvest Threshing', 'アルベール・グレーズ', 'Albert Gleizes',
        1912,
        (select slug from public.art_movements where slug = 'cubism'),
        '国立西洋美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d3/Albert_Gleizes%2C_1912%2C_Le_D%C3%A9piquage_des_Moissons%2C_Harvest_Threshing%2C_oil_on_canvas%2C_269_x_353_cm%2C_National_Museum_of_Western_Art%2C_Tokyo%2C_Japan.jpg/960px-Albert_Gleizes%2C_1912%2C_Le_D%C3%A9piquage_des_Moissons%2C_Harvest_Threshing%2C_oil_on_canvas%2C_269_x_353_cm%2C_National_Museum_of_Western_Art%2C_Tokyo%2C_Japan.jpg', '東京・上野の国立西洋美術館で見られる、キュビスムの大作です。縦約2.7メートル、横約3.5メートルの画面に、麦の収穫と脱穀をする人々、村、遠くの山並みが、たくさんの面に分かれて描かれています。グレーズは、ギャラリーで作品を売るピカソやブラックとは別に、大きな展覧会で発表した「サロン・キュビスム」の中心人物でした。1912年には仲間のメッツァンジェと、キュビスムの理論書『キュビスムについて』を出しています。小さな静物ではなく、大地と人の営みという大きな主題をキュビスムで描こうとした意欲が感じられます。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('都市は立ち上がる', 'The City Rises', 'ウンベルト・ボッチョーニ', 'Umberto Boccioni',
        1910,
        (select slug from public.art_movements where slug = 'futurism'),
        'ニューヨーク近代美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b4/The_City_Rises_by_Umberto_Boccioni_1910.jpg/960px-The_City_Rises_by_Umberto_Boccioni_1910.jpg', 'ミラノの郊外で建設が進む町を描いた大作です。画面の手前では、赤く巨大な馬と、それを必死に引こうとする人々が渦のように動いています。奥には工場の煙突や足場が見えます。細かな色の筆づかいには、点描から発展したイタリアの分割主義の影響が残っていますが、主題は「力」と「動き」そのものです。未来派宣言の翌年、新しい都市を生み出すエネルギーを賛美しようとした作品で、未来派絵画の出発点の一つとされます。馬の体からあふれる光と線の流れを追ってみてください。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('心の状態I：別れ', 'States of Mind I: The Farewells', 'ウンベルト・ボッチョーニ', 'Umberto Boccioni',
        1911,
        (select slug from public.art_movements where slug = 'futurism'),
        'ニューヨーク近代美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/26/States_of_Mind-_The_Farewells_by_Umberto_Boccioni%2C_1911.jpeg/960px-States_of_Mind-_The_Farewells_by_Umberto_Boccioni%2C_1911.jpeg', '駅での別れの場面を描いた、《心の状態》三部作の一枚です。蒸気機関車、抱き合う人々、電線や鉄塔が、波打つ線とキュビスム風の面の中で溶け合っています。ボッチョーニは、目に見える駅の光景だけでなく、別れのときの気持ちの揺れや騒がしさを、線の動きで表そうとしました。三部作は「別れ」「行く人々」「残る人々」からなり、場面ごとに線の向きや形が変わります。パリのキュビスムから学んだ分解の方法を、未来派らしい「動きと感情」の表現に結びつけた作品です。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('サッカー選手のダイナミズム', 'Dynamism of a Soccer Player', 'ウンベルト・ボッチョーニ', 'Umberto Boccioni',
        1913,
        (select slug from public.art_movements where slug = 'futurism'),
        'ニューヨーク近代美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/26/WLA_moma_Umberto_Boccioni_Dynamism_of_a_Soccer_Player_1913.jpg/960px-WLA_moma_Umberto_Boccioni_Dynamism_of_a_Soccer_Player_1913.jpg', 'ボールを蹴る選手を描いた作品ですが、人の形ははっきりとは見えず、色と形の渦が画面いっぱいに広がっています。ボッチョーニは、動いている体とまわりの空間が互いに入り込み合う様子を描こうとしました。題名の「ダイナミズム（力動性）」は、未来派が好んで使った言葉です。同じ1913年には、歩く人の動きを彫刻にした《空間における連続性の唯一の形態》も作っています。止まった一瞬ではなく、動きの流れそのものを描くという未来派の目標が、もっとも抽象に近い形で表れた作品です。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('自動車のダイナミズム', 'Racing car', 'ルイジ・ルッソロ', 'Luigi Russolo',
        1912,
        (select slug from public.art_movements where slug = 'futurism'),
        'ポンピドゥー・センター（国立近代美術館）', 'https://upload.wikimedia.org/wikipedia/commons/5/55/Luigi_Russolo_dynamism-of-a-car-1913.jpg', '疾走する自動車を、ほとんど抽象に近い形で描いた作品です。横に積み重なる赤い矢じりのような形が、車の進む方向と、空気を切り裂くような速さを示しています。未来派は、自動車を新しい時代の美の象徴としてたたえました。作者のルッソロは画家であるとともに、1913年に「騒音芸術」を唱え、騒音を出す楽器を自ら作ったことでも知られます。この絵からも、目に見える速さだけでなく、エンジンのうなりまで描こうとした意図が感じられます。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('研ぎ師', 'The Knife Grinder', 'カジミール・マレーヴィチ', 'Kazimir Malevich',
        1912,
        (select slug from public.art_movements where slug = 'futurism'),
        'イェール大学美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/58/The_Knife_Grinder_Principle_of_Glittering_by_Kazimir_Malevich.jpeg/960px-The_Knife_Grinder_Principle_of_Glittering_by_Kazimir_Malevich.jpeg', 'ロシアの画家マレーヴィチが、刃物を研ぐ職人の姿を描いた作品です。手や足、階段が何度も重ねて描かれ、作業の動きが連続写真のように表されています。形を面に分けるキュビスムと、動きを重ねる未来派を組み合わせたこのスタイルは、ロシアでは「立体未来主義（キュボ・フトゥリズム）」と呼ばれました。マレーヴィチはこの後、1915年に《黒の正方形》を発表し、形をさらに単純にした「シュプレマティスム」へ進みます。未来派の考えがイタリアの外へ広がり、抽象へとつながっていく転換点の一枚です。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('ギャラリーでの騒動', 'Riot in the Gallery', 'ウンベルト・ボッチョーニ', 'Umberto Boccioni',
        1910,
        (select slug from public.art_movements where slug = 'futurism'),
        'ブレラ美術館', 'https://upload.wikimedia.org/wikipedia/commons/3/3b/Umberto_Boccioni%2C_Rissa_in_galleria%2C_Pinacoteca_di_Brera%2C_Milano.jpg', 'ミラノの中心にあるアーケード、ガッレリアのカフェの前で起きた騒ぎに、人々が四方から駆け寄っていく場面です。強い電灯の光の下で、群衆の動きが一つの渦になっています。細かな点や短い筆で色を並べる方法には、分割主義の名残が見えます。一方で、群衆、都市の夜、人工の光という主題は、まさに未来派が描こうとした近代の姿です。未来派の絵画宣言が出された1910年の作品で、古い技法から新しい主題へと移り変わる時期のボッチョーニの姿がよくわかります。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('ダダの頭部', 'Tête Dada', 'ゾフィー・トイバー＝アルプ', 'Sophie Taeuber-Arp',
        1920,
        (select slug from public.art_movements where slug = 'dada'),
        'ポンピドゥー・センター（国立近代美術館）', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cc/Sophie_taeuber-arp%2C_testa_dada%2C_1920%2C_02.JPG/960px-Sophie_taeuber-arp%2C_testa_dada%2C_1920%2C_02.JPG', 'チューリヒのダダに参加したトイバー＝アルプは、工芸学校で織物などを教えながら、絵画、人形、デザインと幅広く制作しました。この作品は、ろくろで挽いた木に色を塗った頭部の像で、1918年から1920年にかけて作った頭部のシリーズの最後のものとされます。目や鼻は曲線と平らな色面に置きかえられ、額には「Dada」の文字と年が描かれています。顔の特徴は残しつつ、肖像や彫刻の決まりごとを、工芸の技法と鮮やかな色で軽やかに崩しているのが見どころです。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('ウントの絵', 'The Und-Picture', 'クルト・シュヴィッタース', 'Kurt Schwitters',
        1919,
        (select slug from public.art_movements where slug = 'dada'),
        'シュトゥットガルト州立美術館', 'https://upload.wikimedia.org/wikipedia/commons/f/fc/DasUndbild.jpg', 'ハノーファーのシュヴィッタースは、切符、包装紙、新聞の切れ端など、町で拾った素材を貼り合わせて作品を作りました。「und」はドイツ語で「そして」を意味し、1919年はシュヴィッタースが独自のコラージュを本格的に始めた年です。シュヴィッタースは、銀行の広告の文字から切り取った「Merz（メルツ）」という言葉を自分の作品の総称にしました。キュビスムのコラージュを受け継ぎながら、捨てられた物から新しい秩序を作り出そうとしたのが彼のダダです。紙片の色や文字の並びを、詩を読むように楽しんでみてください。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content)
values ('メルツ絵1A（精神科医）', 'Merzbild 1A (The Psychiatrist)', 'クルト・シュヴィッタース', 'Kurt Schwitters',
        1919,
        (select slug from public.art_movements where slug = 'dada'),
        'ティッセン＝ボルネミッサ美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8a/Merzbild_1A_%28The_Psychiatrist%29_%281919%29.jpg/960px-Merzbild_1A_%28The_Psychiatrist%29_%281919%29.jpg', 'シュヴィッタースが「メルツ」と名づけた作品群の、ごく初期の一点とされます。油絵具で描いた画面に、さまざまな物や紙が貼り付けられ、絵画とオブジェの間のような作品になっています。シュヴィッタースは、第一次世界大戦後の混乱した社会で、壊れたものの断片から新しいものを組み立て直すことを考えていました。ベルリンのダダのような政治的な激しさよりも、素材の組み合わせの美しさを大切にしたのが特徴です。貼られた物の質感や、絵具との境目に近づいて見ると、作品の作られ方がよくわかります。')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content;
